```java
import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import java.util.regex.*;

import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    private static final Pattern CSRF_JSON_PATTERN =
        Pattern.compile("\"csrf\"\\s*:\\s*\"([^\"]+)\"");

    {
        String baseUrl = System.getenv("BASE_URL") != null
            ? System.getenv("BASE_URL")
            : "http://127.0.0.1:8000";

        HttpProtocolBuilder httpProtocol = http
            .baseUrl(baseUrl)
            .disableAutoRedirect()
            .userAgentHeader("gatling-shop-flow");

        ChainBuilder flow = exec(session -> session
                .remove("csrf")
                .remove("cartId")
                .remove("etag")
                .remove("idem")
                .remove("loginLocation")
                .remove("loginStatus")
                .remove("loginBody")
                .remove("followBody")
                .remove("patchStatus")
                .remove("patchCsrf")
                .remove("patchEtag")
                .remove("newCsrf")
                .remove("retryCsrf")
                .remove("retryEtag")
                .remove("orderCsrf")
                .remove("productId")
                .remove("variantId")
        )
        .exec(session -> {
            Long uid = session.getLong("userId");
            String username = uid != null && uid >= 1 && uid <= 16
                ? "bench-" + uid
                : "bench";
            return session.set("username", username).set("password", "bench");
        })

        // Fresh login form and CSRF extraction
        .exec(http("GET_login_form")
            .get("/v2/login-form")
            .check(status().is(200))
            .check(css("input[name='csrf']", "value").saveAs("csrf"))
        )

        .exec(http("POST_login")
            .post("/v2/login")
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody("{\"username\":\"#{username}\",\"password\":\"#{password}\",\"csrf\":\"#{csrf}\"}"))
            .asJson()
            .check(status().in(200, 302))
            .check(status().saveAs("loginStatus"))
            .check(header("Location").optional().saveAs("loginLocation"))
            .check(bodyString().saveAs("loginBody"))
        )

        .exec(session -> {
            int status = session.getInt("loginStatus");
            if (status == 200) {
                String body = session.getString("loginBody");
                Matcher m = CSRF_JSON_PATTERN.matcher(body);
                if (m.find()) {
                    return session.set("csrf", m.group(1));
                }
                return session.markAsFailed();
            }
            return session;
        })

        .doIf(session -> session.contains("loginStatus")
                && session.getInt("loginStatus") == 302
                && session.contains("loginLocation"))
        .then(
            exec(http("GET_login_redirect")
                .get("#{loginLocation}")
                .check(status().in(200, 302))
                .check(bodyString().saveAs("followBody"))
            )
            .exec(session -> {
                String body = session.getString("followBody");
                if (body != null) {
                    Matcher m = CSRF_JSON_PATTERN.matcher(body);
                    if (m.find()) {
                        return session.set("csrf", m.group(1));
                    }
                }
                return session;
            })
        )

        // Catalog: pick first available product/variant.
        .exec(http("GET_catalog")
            .get("/v2/catalog")
            .check(status().is(200))
            .check(jsonPath("$.data.products[0].id").saveAs("productId"))
            .check(jsonPath("$.data.products[0].variants[0].id").saveAs("variantId"))
        )

        // Create one cart.
        .exec(http("POST_create_cart")
            .post("/v2/carts")
            .header("X-CSRF-Token", "#{csrf}")
            .body(StringBody("{\"product_id\":\"#{productId}\",\"variant_id\":\"#{variantId}\"}"))
            .asJson()
            .check(status().is(201))
            .check(jsonPath("$.id").saveAs("cartId"))
            .check(header("ETag").saveAs("etag"))
            .check(jsonPath("$.csrf").optional().saveAs("newCsrf"))
        )
        .exec(session -> {
            if (session.contains("newCsrf")) {
                session = session.set("csrf", session.getString("newCsrf")).remove("newCsrf");
            }
            session = session.set("idem", "order-" + session.getString("cartId"));
            return session;
        })

        // First PATCH quantity. 412 is expected as a possible optimistic-lock event.
        .exec(http("PATCH_cart_quantity")
            .patch("/v2/carts/#{cartId}")
            .header("X-CSRF-Token", "#{csrf}")
            .header("If-Match", "#{etag}")
            .body(StringBody("{\"quantity\":1}"))
            .asJson()
            .check(status().in(200, 204, 412))
            .check(status().saveAs("patchStatus"))
            .check(header("ETag").optional().saveAs("patchEtag"))
            .check(jsonPath("$.csrf").optional().saveAs("patchCsrf"))
        )
        .exec(session -> {
            int status = session.getInt("patchStatus");
            if (status == 200 || status == 204) {
                if (session.contains("patchCsrf")) {
                    session = session.set("csrf", session.getString("patchCsrf")).remove("patchCsrf");
                }
                if (session.contains("patchEtag")) {
                    session = session.set("etag", session.getString("patchEtag")).remove("patchEtag");
                }
                return session.remove("patchStatus");
            }
            return session;
        })

        // On 412, re-read ETag and retry the same payload exactly once.
        .doIf(session -> session.contains("patchStatus") && session.getInt("patchStatus") == 412)
        .then(
            exec(http("GET_cart_for_retry")
                .get("/v2/carts/#{cartId}")
                .check(status().is(200))
                .check(header("ETag").saveAs("etag"))
            )
            .exec(http("PATCH_cart_quantity_retry")
                .patch("/v2/carts/#{cartId}")
                .header("X-CSRF-Token", "#{csrf}")
                .header("If-Match", "#{etag}")
                .body(StringBody("{\"quantity\":1}"))
                .asJson()
                .check(status().is(200))
                .check(header("ETag").optional().saveAs("retryEtag"))
                .check(jsonPath("$.csrf").optional().saveAs("retryCsrf"))
            )
