```javascript
import http from 'k6/http';
import { sleep } from 'k6';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const PROFILES = [
  { login_csrf: true },
  { login_csrf: true, html_layout: 1, reverse_catalog: true },
];

export const options = {
  scenarios: {
    default: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '10m',
    },
  },
};

function safeJson(text) {
  try {
    return JSON.parse(text);
  } catch (e) {
    return null;
  }
}

function getError(res) {
  const j = safeJson(res.body);
  return j ? j.error : null;
}

function extractCsrf(html) {
  const inputRegex = /<input\b[^>]*>/gi;
  let m;
  while ((m = inputRegex.exec(html)) !== null) {
    const tag = m[0];
    if (!/\btype\s*=\s*(?:"hidden"|'hidden'|hidden\b)/i.test(tag)) continue;
    if (!/\bname\s*=\s*(?:"csrf"|'csrf'|csrf\b)/i.test(tag)) continue;
    const valueMatch = tag.match(/\bvalue\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i);
    if (valueMatch) return valueMatch[1] || valueMatch[2] || valueMatch[3] || '';
    return '';
  }
  return null;
}

function extractInputValue(html, name) {
  const inputRegex = /<input\b[^>]*>/gi;
  let m;
  while ((m = inputRegex.exec(html)) !== null) {
    const tag = m[0];
    const namePattern = new RegExp(`\\bname\\s*=\\s*(?:"${name}"|'${name}'|${name}\\b)`, 'i');
    if (!namePattern.test(tag)) continue;
    const valueMatch = tag.match(/\bvalue\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i);
    if (valueMatch) return valueMatch[1] || valueMatch[2] || valueMatch[3] || '';
    return '';
  }
  return '';
}

function extractFormAction(html) {
  const formRegex = /<form\b[^>]*>/gi;
  let m;
  while ((m = formRegex.exec(html)) !== null) {
    const tag = m[0];
    const actionMatch = tag.match(/\baction\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i);
    if (actionMatch) {
      return actionMatch[1] || actionMatch[2] || actionMatch[3] || '';
    }
  }
  return null;
}

export default function () {
  const jar = http.cookieJar();
  const profile = PROFILES[(__VU - 1) % PROFILES.length];

  let currentCsrf = null;
  let cartId = null;
  let cartEtag = null;

  function doGet(url) {
    return http.get(url, { jar: jar, redirects: 0, timeout: '30s' });
  }

  function doPost(url, body, extraHeaders) {
    const headers = { 'Content-Type': 'application/json' };
    if (currentCsrf) headers['X-CSRF-Token'] = currentCsrf;
    if (extraHeaders) Object.assign(headers, extraHeaders);
    return http.post(url, JSON.stringify(body), { headers: headers, jar: jar, redirects: 0, timeout: '30s' });
  }

  function doPatch(url, body, extraHeaders) {
    const headers = { 'Content-Type': 'application/json' };
    if (currentCsrf) headers['X-CSRF-Token'] = currentCsrf;
    if (extraHeaders) Object.assign(headers, extraHeaders);
    return http.patch(url, JSON.stringify(body), { headers: headers, jar: jar, redirects: 0, timeout: '30s' });
  }

  function login() {
    const formRes = doGet(`${BASE_URL}/v2/login-form`);
    if (formRes.status !== 200) {
      throw new Error(`Login form failed: ${formRes.status}`);
    }
    const formCsrf = extractCsrf(formRes.body);
    if (!formCsrf) {
      throw new Error('CSRF input not found on login form');
    }
    currentCsrf = formCsrf;

    const username = `bench-${((__VU - 1) % 16) + 1}`;
    let res = http.post(`${BASE_URL}/v2/login`, JSON.stringify({
      username: username,
      password: 'bench',
      csrf: formCsrf,
    }), {
      headers: { 'Content-Type': 'application/json' },
      jar: jar,
      redirects: 0,
      timeout: '30s',
    });

    if (res.status === 301 || res.status === 302 || res.status === 303) {
      const location = res.headers['Location'];
      if (!location) {
        throw new Error('Login redirect missing Location header');
      }
      const redirectUrl = location.startsWith('/') ? `${BASE_URL}${location}` : location;
      res = http.get(redirectUrl, { jar: jar, redirects: 0, timeout: '30s' });
    }

    if (res.status !== 200 && res.status !== 201 && res.status !== 202) {
      throw new Error(`Login failed: ${res.status} ${res.body}`);
    }

    const json = safeJson(res.body);
    if (json && json.csrf) {
      currentCsrf = json.csrf;
    } else if (!currentCsrf) {
      currentCsrf = formCsrf;
    }
  }

  function recoverCart() {
    if (!cartId) return;
    const res = http.post(`${BASE_URL}/v2/carts/${cartId}/recover`, JSON.stringify({}), {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': currentCsrf },
      jar: jar,
      redirects: 0,
      timeout: '30s',
    });
    if (res.status !== 200 && res.status !== 201 && res.status !== 202) {
      throw new Error(`Recover cart failed: ${res.status} ${res.body}`);
    }
    const json = safeJson(res.body);
    if (json && json.csrf) currentCsrf = json.csrf;
    const etag = res.headers['ETag'] || res.headers['Etag'];
    if (etag) cartEtag = etag;
  }

  function renewSession() {
    const res = http.post(`${BASE_URL}/v2/session/renew`, JSON.stringify({}), {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': currentCsrf },
      jar: jar,
      redirects: 0,
      timeout: '30s',
    });
    if (res.status === 200 || res.status === 201 || res.status === 202) {
      const json = safeJson(res.body);
      if (json && json.csrf) currentCsrf = json.csrf;
      recoverCart();
      return true;
    }
    if (res.status === 401 && getError(res) === 'session') {
      return false;
    }
    throw new Error(`Session renew failed: ${res.status} ${res.body}`);
  }

  function sessionRecovery() {
    login();
    recoverCart();
  }

  function authPost(url, body, extraHeaders) {
    let res = doPost(url, body, extraHeaders);
    if (res.status === 401) {
      const error = getError(res);
      if (error === 'denied') {
        throw new Error(`401 denied at ${url}`);
      }
      if (error === 'expired') {
        const renewed = renewSession();
        if (!renewed) sessionRecovery();
      } else if (error === 'session') {
        sessionRecovery();
      } else {
        throw new Error(`Unknown 401 at ${url}: ${res.body}`);
      }
      res = doPost(url, body, extraHeaders);
    }
    return res;
  }

  function authPatch(url, body, extraHeaders) {
    let res = doPatch(url, body, extraHeaders);
    if (res.status === 401) {
      const error = getError(res);
      if (error === 'denied') {
        throw new Error(`401 denied at ${url}`);
      }
      if (error === 'expired') {
        const renewed = renewSession();
        if (!renewed) sessionRecovery();
      } else if (error === 'session') {
        sessionRecovery();
      } else {
        throw new Error(`Unknown 401 at ${url}: ${res.body}`);
      }
      res = doPatch(url, body, extraHeaders);
    }
    return res;
  }

  function acquireChallengeGrant() {
    const formRes = doGet(`${BASE_URL}/v2/challenge-form`);
    if (formRes.status !== 200) {
      throw new Error(`Challenge form failed: ${formRes.status}`);
    }
    const html = formRes.body;
    const action = extractFormAction(html);
    if (!action) {
      throw new Error('Challenge form action not found');
    }
    const actionUrl = action.startsWith('/') ? `${BASE_URL}${action}` : action;
    const challengeValue = extractInputValue(html, 'challenge');

    let res = http.post(actionUrl, JSON.stringify({ challenge: challengeValue }), {
      headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': currentCsrf },
      jar: jar,
      redirects: 0,
