                    self.etag = new_etag
                    continue

                if resp.status_code == 412:
                    if retried_412:
                        resp.failure("orders 412 after retry")
                        return None
                    retried_412 = True
                    resp.success()
                    new_etag = self.get_cart_etag(cart_id)
                    if not new_etag:
                        return None
                    self.etag = new_etag
                    continue

                resp.failure(f"orders status {resp.status_code}")
                return None

        return None

    def run_journey(self):
        self.cart_id = None
        self.etag = None
        self.grant_id = None
        self.reservation_id = None
        self.idem_key = None

        if not self._fresh_login():
            return

        product_id, variant_id = self.select_product()
        if not product_id:
            return

        self.grant_id = self._obtain_challenge()

        cart_id, etag = self.create_cart(product_id, variant_id, self.grant_id)
        if not cart_id:
            return
        self.cart_id = cart_id
        self.etag = etag

        new_etag = self.get_cart_etag(cart_id)
        if not new_etag:
            return
        self.etag = new_etag

        if not self.patch_cart(cart_id, 1):
            return

        new_etag = self.get_cart_etag(cart_id)
        if not new_etag:
            return
        self.etag = new_etag

        self.do_work_or_browse()

        self.reservation_id = self.create_reservation(cart_id)

        new_etag = self.get_cart_etag(cart_id)
        if new_etag:
            self.etag = new_etag

        self.create_order(cart_id, self.reservation_id)


