        return session.remove(key);
    }

    @SuppressWarnings("unchecked")
    private static Session selectFromCatalog(Session session) {
        Object raw = session.get("catalog_products");
        if (raw instanceof List) {
            List<Object> products = (List<Object>) raw;
            for (Object pObj : products) {
                if (!(pObj instanceof Map)) continue;
                Map<String, Object> product = (Map<String, Object>) pObj;
                Object productId = product.get("id");
                Object variantsObj = product.get("variants");

                if (!(variantsObj instanceof List)) continue;
                List<Object> variants = (List<Object>) variantsObj;

                for (Object vObj : variants) {
                    if (!(vObj instanceof Map)) continue;
                    Map<String, Object> variant = (Map<String, Object>) vObj;
                    Object inStockObj = variant.get("in_stock");
                    boolean inStock = Boolean.TRUE.equals(inStockObj)
                            || "true".equalsIgnoreCase(String.valueOf(inStockObj))
                            || "1".equals(String.valueOf(inStockObj));

                    if (inStock) {
                        return session
                                .set("product_id", String.valueOf(productId))
                                .set("variant_id", String.valueOf(variant.get("id")))
                                .set("found_stock", true);
                    }
                }
            }
        }
        return session.set("found_stock", false);
    }

    private static Session buildCartBody(Session session) {
        String body = "{\"product_id\":\"" + session.getString("product_id")
                + "\",\"variant_id\":\"" + session.getString("variant_id");
        if (session.contains("grant_id")) {
            body += "\",\"grant_id\":\"" + session.getString("grant_id") + "\"";
        } else {
            body += "\"";
        }
        body += "}";
        return session.set("cart_body", body);
    }

    ChainBuilder resetJourney = exec(session -> session
            .remove("csrf")
            .remove("login_location")
            .remove("login_csrf")
            .remove("challenge_action")
            .remove("challenge_value")
            .remove("challenge_location")
            .remove("challenge_csrf")
            .remove("grant_id")
            .remove("product_id")
            .remove("variant_id")
            .remove("found_stock")
            .remove("cart_id")
            .remove("etag")
            .remove("order_id")
            .remove("order_csrf")
            .remove("cart_csrf")
            .remove("cart_body")
            .remove("work_attempt")
            .remove("work_done")
            .remove("work_retry_after")
    );

    ChainBuilder login = exec(
            http("login-form")
                    .get("/v2/login-form")
                    .check(status().is(200))
                    .check(css("input[name=csrf]", "value").saveAs("csrf"))
    ).exec(
            http("login")
                    .post("/v2/login")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody("{\"username\":\"#{username}\",\"password\":\"bench\",\"csrf\":\"#{csrf}\"}"))
                    .check(status().in(200, 302))
                    .check(header("Location").optional().saveAs("login_location"))
                    .check(jsonPath("$.csrf").optional().saveAs("login_csrf"))
    ).doIf(session -> session.contains("login_location")).then(
            http("login-redirect")
                    .get("#{login_location}")
                    .check(status().is(200))
                    .check(jsonPath("$.csrf").saveAs("login_csrf"))
    ).exec(session -> updateCsrf(session, "login_csrf"));

    ChainBuilder challenge = exec(
            http("challenge-form")
                    .get("/v2/challenge-form")
                    .check(status().in(200, 403, 404))
                    .check(css("form[action^='/v2/challenges/']", "action").optional().saveAs("challenge_action"))
                    .check(css("form[action^='/v2/challenges/'] input[name=challenge]", "value").optional().saveAs("challenge_value"))
    ).doIf(session -> session.contains("challenge_action") && session.contains("challenge_value")).then(
            exec(http("solve-challenge")
                    .post("#{challenge_action}")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody("{\"challenge\":\"#{challenge_value}\"}"))
                    .check(status().is(302))
                    .check(header("Location").optional().saveAs("challenge_location"))
                    .check(jsonPath("$.csrf").optional().saveAs("challenge_csrf"))
            ).doIf(session -> session.contains("challenge_location")).then(
                    http("challenge-redirect")
                            .get("#{challenge_location}")
                            .check(status().is(200))
                            .check(jsonPath("$.grant_id").saveAs("grant_id"))
                            .check(jsonPath("$.csrf").optional().saveAs("challenge_csrf"))
            ).exec(session -> updateCsrf(session, "challenge_csrf"))
    );

    ChainBuilder catalogAndCart = exec(
            http("catalog")
                    .get("/v2/catalog")
                    .check(status().is(200))
                    .check(jsonPath("$.data.products[*]").findAll().saveAs("catalog_products"))
    ).exec(session -> selectFromCatalog(session))
            .exec(session -> {
                if (!session.getBoolean("found_stock")) {
                    throw new RuntimeException("No in-stock product found in catalog");
                }
                return session;
            })
            .exec(session -> buildCartBody(session))
            .exec(
                    http("create-cart")
                            .post("/v2/carts")
                            .header("X-CSRF-Token", "#{csrf}")
                            .body(StringBody("#{cart_body}"))
                            .check(status().is(201))
                            .check(jsonPath("$.id").saveAs("cart_id"))
                            .check(header("ETag").saveAs("etag"))
                            .check(jsonPath("$.csrf").optional().saveAs("cart_csrf"))
            ).exec(session -> updateCsrf(session, "cart_csrf"));

