```javascript
import http from 'k6/http';
import { sleep } from 'k6';

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const PASSWORD = 'bench';

export const options = {
  scenarios: {
    flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '5m',
    },
  },
};

function getHeader(res, name) {
  const headers = res.headers || {};
  const lower = name.toLowerCase();
  for (let key in headers) {
    if (key.toLowerCase() === lower) return headers[key];
  }
  return undefined;
}

function resolveUrl(path) {
  if (!path) return BASE;
  if (path.startsWith('http://') || path.startsWith('https://')) return path;
  if (path.startsWith('/')) return BASE + path;
  return BASE + '/' + path;
}

function parseJson(res) {
  try {
    return res.json();
  } catch (_) {
    return {};
  }
}

function parseInputs(html) {
  const inputs = [];
  const tagRe = /<input\b([^>]*)>/gi;
  let m;
  while ((m = tagRe.exec(html)) !== null) {
    const attrs = {};
    const attrStr = m[1];
    const attrRe = /([a-zA-Z_:][-a-zA-Z0-9_:.]*)\s*=\s*("([^"]*)"|'([^']*)'|([^\s"'=<>`]+))/g;
    let a;
    while ((a = attrRe.exec(attrStr)) !== null) {
      attrs[a[1].toLowerCase()] = a[3] !== undefined ? a[3] : (a[4] !== undefined ? a[4] : a[5]);
    }
    inputs.push(attrs);
  }
  return inputs;
}

function getInputValue(html, name) {
  const inputs = parseInputs(html);
  for (const inp of inputs) {
    if (inp.name === name) {
      return inp.value !== undefined ? inp.value : '';
    }
  }
  return null;
}

function parseFormAction(html) {
  const re = /<form\b([^>]*)>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const attrs = {};
    const attrStr = m[1];
    const attrRe = /([a-zA-Z_:][-a-zA-Z0-9_:.]*)\s*=\s*("([^"]*)"|'([^']*)'|([^\s"'=<>`]+))/g;
    let a;
    while ((a = attrRe.exec(attrStr)) !== null) {
      attrs[a[1].toLowerCase()] = a[3] !== undefined ? a[3] : (a[4] !== undefined ? a[4] : a[5]);
    }
    if (attrs.action) return attrs.action;
  }
  return null;
}

function maybeUpdateCsrf(state, res) {
  try {
    const obj = res.json();
    if (obj && obj.csrf) {
      state.csrf = obj.csrf;
    }
  } catch (_) {}
}

function getNoRedirect(url) {
  return http.get(url, { redirects: 0 });
}

function performLogin(state) {
  const formRes = getNoRedirect(`${BASE}/v2/login-form`);
  if (formRes.status !== 200) throw new Error('login form status ' + formRes.status);
  const loginCsrf = getInputValue(formRes.body, 'csrf');
  if (!loginCsrf) throw new Error('login csrf not found');

  let res = http.post(`${BASE}/v2/login`, JSON.stringify({
    username: state.username,
    password: PASSWORD,
    csrf: loginCsrf,
  }), {
    redirects: 0,
    headers: { 'Content-Type': 'application/json' },
  });

  if (res.status === 302) {
    const loc = getHeader(res, 'Location');
    if (!loc) throw new Error('login redirect missing Location');
    res = http.get(resolveUrl(loc), { redirects: 0 });
  }

  if (res.status !== 200) throw new Error('login status ' + res.status + ' body ' + res.body);

  maybeUpdateCsrf(state, res);
  if (!state.csrf) {
    const htmlCsrf = getInputValue(res.body, 'csrf');
    if (htmlCsrf) state.csrf = htmlCsrf;
    else state.csrf = loginCsrf;
  }
}

function authedRequest(state, method, url, body, opts = {}, isRetry = false) {
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': state.csrf,
  };
  if (opts.ifMatch) headers['If-Match'] = opts.ifMatch;
  if (opts.idempotencyKey) headers['Idempotency-Key'] = opts.idempotencyKey;

  const res = http.request(method, url, body, {
    redirects: 0,
    headers,
  });

  if (res.status === 401 && !isRetry) {
    let err = {};
    try {
      err = res.json();
    } catch (_) {}

    if (err.error === 'expired') {
      const renewRes = http.post(`${BASE}/v2/session/renew`, '{}', {
        redirects: 0,
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': state.csrf,
        },
      });
      if (renewRes.status === 401) {
        performLogin(state);
      } else {
        maybeUpdateCsrf(state, renewRes);
      }

      if (state.cartId) {
        http.post(`${BASE}/v2/carts/${state.cartId}/recover`, '{}', {
          redirects: 0,
          headers: {
            'Content-Type': 'application/json',
            'X-CSRF-Token': state.csrf,
          },
        });
      }

      return authedRequest(state, method, url, body, opts, true);
    }

    if (err.error === 'session') {
      performLogin(state);
      if (state.cartId) {
        http.post(`${BASE}/v2/carts/${state.cartId}/recover`, '{}', {
          redirects: 0,
          headers: {
            'Content-Type': 'application/json',
            'X-CSRF-Token': state.csrf,
          },
        });
      }
      return authedRequest(state, method, url, body, opts, true);
    }

    if (err.error === 'denied') {
      throw new Error('401 denied');
    }

    throw new Error('401 unknown: ' + res.body);
  }

  return res;
}

function isInStock(v) {
  return v && (
    v.in_stock === true ||
    v.in_stock === 1 ||
    v.in_stock === 'true' ||
    v.in_stock === '1'
  );
}

function extractProducts(data) {
  if (!data) return [];
  const d = data.data || data;
  if (Array.isArray(d)) return d;
  if (Array.isArray(d.products)) return d.products;
  if (d.product) return [d.product];
  return [];
}

function hasEligible(products) {
  return products.some(p => p && Array.isArray(p.variants) && p.variants.some(isInStock));
}

function pickEligible(products) {
  for (const p of products) {
    if (!p || !Array.isArray(p.variants)) continue;
    for (const v of p.variants) {
      if (isInStock(v)) {
        return { product_id: p.id, variant_id: v.id };
      }
    }
  }
  throw new Error('eligible product disappeared');
}

function selectEligibleProduct() {
  let res = getNoRedirect(`${BASE}/v2/catalog`);
  if (res.status !== 200) throw new Error('catalog status ' + res.status);
  let data = parseJson(res);
  let products = extractProducts(data);
  if (hasEligible(products)) return pickEligible(products);

  let next = data.next;
  let pages = 0;

  while (pages < 3) {
    const url = resolveUrl(next || '/v2/catalog/page');
    res = getNoRedirect(url);
    if (res.status !== 200) throw new Error('catalog page status ' + res.status);
    data = parseJson(res);
    products = extractProducts(data);
    if (hasEligible(products)) return pickEligible(products);
    next = data.next;
    if (!next) break;
    pages++;
  }

  throw new Error('no eligible in-stock product found');
}

function performChallenge(state) {
  const formRes = getNoRedirect(`${BASE}/v2/challenge-form`);
  if (formRes.status !== 200) throw new Error('challenge form status ' + formRes.status);

  const html = formRes.body;
  const action = parseFormAction(html);
  const challengeValue = getInputValue(html, 'challenge');
  if (!action) throw new Error('challenge action missing');

  const body = JSON.stringify({ challenge: challengeValue !== null ? challengeValue : '' });
  const claimRes = authedRequest(state, 'POST', resolveUrl(action), body, {}, false);

  let finalRes = claimRes;
  if (claimRes.status === 302) {
    const loc = getHeader(claimRes, 'Location');
    if (!loc) throw new Error('challenge redirect missing Location');
    finalRes = http.get(resolveUrl(loc), { redirects: 0 });
  }

  if (finalRes.status !== 200) throw new Error('challenge final status ' + finalRes.status);

  maybeUpdateCsrf(state, finalRes);
  const data = parseJson(finalRes);
  if (!data.grant_id) throw new Error('grant_id missing');
  state.grantId = data.grant_id;
}

function createCart(state, product) {
  const body = JSON.stringify({
    product_id: product.product_id,
    variant_id: product.variant_id,
    grant_id: state.grantId,
  });

  const res = authedRequest(state, 'POST', `${BASE}/v2/carts`, body, {}, false);
  if (res.status !== 201) throw new Error('cart create status ' + res.status + ' body ' + res.body);

  maybeUpdateCsrf(state, res);
  const data = parseJson(res);
  if (!data.id) throw new Error('cart id missing');

  state.cartId = data.id;
  const etag = getHeader(res, 'ETag');
  if (etag) state.cartEtag = etag;
}

function patchQuantity(state) {
  const url = `${BASE}/v2/carts/${state.cartId}`;
  const payload = JSON.stringify({ quantity: 2 });

  let res = authedRequest(state, 'PATCH', url, payload, { ifMatch: state.cartEtag }, false);

  if (res.status === 412) {
    const getRes = getNoRedirect(url);
    if (getRes.status === 200) {
      const etag = getHeader(getRes, 'ETag');
      if (etag) state.cartEtag = etag;
      res = authedRequest(state, 'PATCH', url, payload, { ifMatch: state.cartEtag }, false);
    }
  }

  if (res.status !== 200 && res.status !== 201 && res.status !== 204) {
    throw new Error('patch status ' + res.status + ' body ' + res.body);
  }

  maybeUpdateCsrf(state, res);
  const etag = getHeader(res, 'ETag');
  if (etag) state.cartEtag = etag;
}

function reserve(state) {
  const res = authedRequest(state, 'POST', `${BASE}/v2/reservations`, JSON.stringify({ cart_id: state.cartId }), {}, false);
  if (res.status !== 202) throw new Error('reservation status ' + res.status + ' body ' + res.body);

  const data = parseJson(res);
  maybeUpdateCsrf(state, res);
  if (!data.status_url) throw new Error('reservation status_url missing');

  const statusUrl = resolveUrl(data.status_url);
  let reservationId = null;

  for (let i = 0; i < 5; i++) {
    sleep(0.05);
    const pollRes = http.get(statusUrl, { redirects: 0 });
    const pollData = parseJson(pollRes);

    if (pollData.status === 'ready' && pollData.reservation_id) {
      reservationId = pollData.reservation_id;
      maybeUpdateCsrf(state, pollRes);
      break;
    } else if (pollData.status === 'failed') {
      throw new Error('reservation failed');
    }
  }

  if (!reservationId) throw new Error('reservation not ready');
  state.reservationId = reservationId;
}

function placeOrder(state) {
  const bodyObj = { cart_id: state.cartId };
  if (state.reservationId) bodyObj.reservation_id = state.reservationId;

  const body = JSON.stringify(bodyObj);
  const idemKey = `idem-${state.cartId}`;

  let res = authedRequest(state, 'POST', `${BASE}/v2/orders`, body, {
    ifMatch: state.cartEtag,
    idempotencyKey: idemKey,
  }, false);

  if (res.status === 412) {
    const getRes = getNoRedirect(`${BASE}/v2/carts/${state.cartId}`);
    if (getRes.status === 200) {
      const etag = getHeader(getRes, 'ETag');
      if (etag) state.cartEtag = etag;
      res = authedRequest(state, 'POST', `${BASE}/v2/orders`, body, {
        ifMatch: state.cartEtag,
        idempotencyKey: idemKey,
      }, false);
    }
  }

  if (res.status !== 201) {
    if (res.status === 200) {
      const od = parseJson(res);
      if (od.accepted === false) throw new Error('order not accepted');
      throw new Error('unexpected 200 accepted true');
    }
    throw new Error('order status ' + res.status + ' body ' + res.body);
  }

  const data = parseJson(res);
  if (data.accepted !== true) throw new Error('order accepted not true');
  maybeUpdateCsrf(state, res);
}

export default function () {
  const state = {
    username: `bench-${__VU}`,
    csrf: '',
    cartId: null,
    cartEtag: null,
    grantId: null,
    reservationId: null,
  };

  performLogin(state);
  const product = selectEligibleProduct();
  performChallenge(state);
  createCart(state, product);
  patchQuantity(state);
  reserve(state);
  placeOrder(state);
}
