import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;

import java.time.Duration;
import java.util.*;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ModelSimulation extends Simulation {

    private final HttpProtocolBuilder httpProtocol = http
            .baseUrl(System.getenv("BASE_URL"))
            .acceptHeader("application/json")
            .contentTypeHeader("application/json")
            .userAgentHeader("gatling-follower")
            .followRedirect(false);

    private ChainBuilder login() {
        return exec(
                http("Get Login Form")
                        .get("/v2/login-form")
                        .check(
                                status().is(200),
                                css("input[name='csrf']", "value").saveAs("csrf")
                        )
        )
        .exec(
                http("Post Login")
                        .post("/v2/login")
                        .header("X-CSRF-Token", session -> strValue(session, "csrf"))
                        .body(StringBody(session -> {
                            String username = strValue(session, "username");
                            String csrf = jsonEscape(strValue(session, "csrf"));
                            return String.format(
                                    "{\"username\":\"%s\",\"password\":\"bench\",\"csrf\":\"%s\"}",
                                    username,
                                    csrf
                            );
                        }))
                        .check(
                                status().is(200).or(status().is(302)),
                                header("Location").optional().saveAs("loginLocation"),
                                bodyString().saveAs("loginBody")
                        )
        )
        .exec(session -> {
            String csrf = extractJsonString(strValue(session, "loginBody"), "csrf");
            if (csrf != null) {
                session = session.set("csrf", csrf);
            }
            return session;
        })
        .doIf(session -> {
            String location = strValue(session, "loginLocation");
            return location != null && !location.isEmpty();
        })
            .exec(
                    http("Get Login Redirect")
                            .get(session -> strValue(session, "loginLocation"))
                            .check(
                                    status().is(200),
                                    bodyString().saveAs("loginBody")
                            )
            )
            .exec(session -> {
                String csrf = extractJsonString(strValue(session, "loginBody"), "csrf");
                if (csrf != null) {
                    session = session.set("csrf", csrf);
                }
                return session;
            });
    }

    private ChainBuilder selectCatalogItem() {
        return exec(session -> session
                .set("pageCount", 1)
                .set("found", false)
                .set("nextUrl", null)
                .set("pageProducts", null)
        )
        .exec(
                http("Catalog First Page")
                        .get("/v2/catalog")
                        .check(
                                status().is(200),
                                jsonPath("$.next").find().optional().saveAs("nextUrl"),
                                jsonPath("$.data.products[*]").findAll().optional().saveAs("pageProducts")
                        )
        )
        .exec(this::selectEligibleFromPage)
        .exec(asLongAs(session -> {
            String next = strValue(session, "nextUrl");
            return intValue(session, "pageCount") < 3
                    && !boolValue(session, "found", false)
                    && next != null;
        }).on(
                exec(http("Catalog Page")
                        .get(session -> strValue(session, "nextUrl"))
                        .check(
                                status().is(200),
                                jsonPath("$.next").find().optional().saveAs("nextUrl"),
                                jsonPath("$.data.products[*]").findAll().optional().saveAs("pageProducts")
                        )
                )
                .exec(session -> session.set("pageCount", intValue(session, "pageCount") + 1))
                .exec(this::selectEligibleFromPage)
        ))
        .exec(session -> {
            if (!boolValue(session, "found", false)) {
                throw new RuntimeException("No eligible in-stock item found within 3 catalog pages");
            }
            return session;
        });
    }

    private Session selectEligibleFromPage(Session session) {
        Object productsRaw = session.get("pageProducts");
        if (productsRaw instanceof List) {
            for (Object productObj : (List<?>) productsRaw) {
                if (!(productObj instanceof Map)) {
                    continue;
                }
                Map<?, ?> product = (Map<?, ?>) productObj;
                Object variantsObj = product.get("variants");
                if (!(variantsObj instanceof List)) {
                    continue;
                }
                for (Object variantObj : (List<?>) variantsObj) {
                    if (!(variantObj instanceof Map)) {
                        continue;
                    }
                    Map<?, ?> variant = (Map<?, ?>) variantObj;
                    Object inStockObj = variant.get("in_stock");
                    boolean inStock = Boolean.TRUE.equals(inStockObj)
                            || "true".equalsIgnoreCase(String.valueOf(inStockObj));
                    if (inStock) {
                        session = session.set("selectedProductId", String.valueOf(product.get("id")));
                        session = session.set("selectedVariantId", String.valueOf(variant.get("id")));
                        session = session.set("found", true);
                        return session;
                    }
                }
            }
        }
        return session.set("found", false);
    }

    private ChainBuilder createCart() {
        return exec(http("Create Cart")
                .post("/v2/carts")
                .header("X-CSRF-Token", session -> strValue(session, "csrf"))
                .body(StringBody(session -> {
                    String productId = strValue(session, "selectedProductId");
                    String variantId = strValue(session, "selectedVariantId");
                    return "{\"product_id\":" + productId + ",\"variant_id\":" + variantId + "}";
                }))
                .check(
                        status().is(201),
                        jsonPath("$.id").ofString().saveAs("cartId"),
                        jsonPath("$.csrf").optional().saveAs("csrf"),
                        header("ETag").optional().saveAs("cartEtag")
                )
        );
    }

    private ChainBuilder getCart() {
        return exec(http("Get Cart")
                .get(session -> "/v2/carts/" + strValue(session, "cartId"))
                .check(
                        status().is(200),
                        header("ETag").saveAs("cartEtag")
                )
        );
    }

    private ChainBuilder patchCart() {
        return exec(http("Patch Cart")
                .patch(session -> "/v2/carts/" + strValue(session, "cartId"))
                .header("X-CSRF-Token", session -> strValue(session, "csrf"))
                .header("If-Match", session -> strValue(session, "cartEtag"))
                .body(StringBody("{\"quantity\":1}"))
                .check(
                        status().saveAs("patchStatus"),
                        status().is(200).or(status().is(204)).or(status().is(412)),
                        header("ETag").optional().saveAs("cartEtag"),
                        bodyString().saveAs("patchBody")
                )
        )
        .exec(session -> {
            String csrf = extractJsonString(strValue(session, "patchBody"), "csrf");
            if (csrf != null) {
                session = session.set("csrf", csrf);
            }
            return session;
        })
        .doIf(session -> "412".equals(String.valueOf(session.get("patchStatus"))))
            .exec(http("Re-Read Cart After 412")
                    .get(session -> "/v2/carts/" + strValue(session, "cartId"))
                    .check(
                            status().is(200),
                            header("ETag").saveAs("cartEtag")
                    )
            )
            .exec(http("Patch Cart Retry")
                    .patch(session -> "/v2/carts/" + strValue(session, "cartId"))
                    .header("X-CSRF-Token", session -> strValue(session, "csrf"))
                    .header("If-Match", session -> strValue(session, "cartEtag"))
                    .body(StringBody("{\"quantity\":1}"))
                    .check(
                            status().is(200).or(status().is(204)),
                            header("ETag").optional().saveAs("cartEtag"),
                            bodyString().saveAs("patchBody")
                    )
            )
            .exec(session -> {
                String csrf = extractJsonString(strValue(session, "patchBody"), "csrf");
                if (csrf != null) {
                    session = session.set("csrf", csrf);
                }
                return session;
            });
    }

    private ChainBuilder reserve() {
        return exec(http("Create Reservation")
                .post("/v2/reservations")
                .header("X-CSRF-Token", session -> strValue(session, "csrf"))
                .body(StringBody(session -> "{\"cart_id\":" + strValue(session, "cartId") + "}"))
                .check(
