def extract_csrf_from_html(html):
    if not html:
        return None
    for tag in re.finditer(r'<input\b[^>]*>', html, re.I):
        tag_text = tag.group(0)
        if re.search(r'\bname\s*=\s*["\']?\s*csrf\s*["\']?(?=[\s>])', tag_text, re.I):
            vm = re.search(r'\bvalue\s*=\s*["\']([^"\']*)["\']', tag_text, re.I)
            if vm:
                return vm.group(1)
            vm = re.search(r'\bvalue\s*=\s*([^\s>]+)', tag_text, re.I)
            if vm:
                return vm.group(1)
    return None


