    else if (pageData.data && pageData.data.product) product = pageData.data.product;
    else if (pageData.data && Array.isArray(pageData.data.products) && pageData.data.products.length > 0) product = pageData.data.products[0];

    if (product && product.id && Array.isArray(product.variants)) {
      for (const variant of product.variants) {
        if (variant && variant.id && variant.in_stock) {
          return { product_id: product.id, variant_id: variant.id };
        }
      }
    }

    next = (pageData && pageData.next) || (pageData.data && pageData.data.next) || null;
    pages++;
  }

  throw new Error('no in-stock product found in catalog');
}

function createCart(baseUrl, csrf, productId, variantId) {
  const payload = JSON.stringify({
    product_id: productId,
    variant_id: variantId,
  });
  const params = {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
    redirects: 0,
  };
  const res = http.post(baseUrl + '/v2/carts', payload, params);
  if (res.status !== 201) {
    throw new Error('cart creation failed status ' + res.status + ' body ' + res.body);
  }

  const data = parseJson(res, 'cart creation');
  const etag = getHeader(res, 'ETag');
  if (!etag) {
    throw new Error('cart creation missing ETag');
  }
  const nextCsrf = data.csrf || csrf;
  return { cartId: data.id, etag: etag, csrf: nextCsrf, data: data };
}

function getCart(baseUrl, cartId) {
  const res = http.get(baseUrl + '/v2/carts/' + cartId, { redirects: 0 });
  if (res.status !== 200) {
    throw new Error('get cart failed status ' + res.status + ' body ' + res.body);
  }
  const etag = getHeader(res, 'ETag');
  if (!etag) {
    throw new Error('get cart missing ETag');
  }
  let data = {};
  if (res.body && res.body.length > 0) {
    try {
      data = JSON.parse(res.body);
    } catch (e) {
      // ignore body parse errors for GET cart; ETag is the required part
    }
  }
  return { etag: etag, csrf: data.csrf || null, data: data };
}

function patchCart(baseUrl, csrf, cartId, etag, quantity) {
  const payload = JSON.stringify({ quantity: quantity });
  const params = {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'If-Match': etag,
    },
    redirects: 0,
  };
  return http.patch(baseUrl + '/v2/carts/' + cartId, payload, params);
}

function postOrder(baseUrl, csrf, cartId, etag, idempotencyKey) {
  const payload = JSON.stringify({ cart_id: cartId });
  const params = {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
      'If-Match': etag,
      'Idempotency-Key': idempotencyKey,
    },
    redirects: 0,
  };
  return http.post(baseUrl + '/v2/orders', payload, params);
}

export default function () {
  try {
    if (http.cookieJar && typeof http.cookieJar().clear === 'function') {
      http.cookieJar().clear();
    }
  } catch (e) {
    // cookie jar clearing is best-effort; per-journey login will establish fresh session
  }

  const vu = __VU;
  const iter = __ITER;
  const userNum = ((vu - 1) * 2 + (iter % 2)) + 1;
  const username = 'bench-' + (((userNum - 1) % 16) + 1);
  const password = 'bench';
  const quantity = 2;

  let csrf = login(BASE_URL, username, password);

  const product = getCatalogProduct(BASE_URL);
  const cart = createCart(BASE_URL, csrf, product.product_id, product.variant_id);

  csrf = cart.csrf;
  let etag = cart.etag;
  const cartId = cart.cartId;

  let patchRes = patchCart(BASE_URL, csrf, cartId, etag, quantity);

  if (patchRes.status === 412) {
    const freshCart = getCart(BASE_URL, cartId);
    if (freshCart.csrf) csrf = freshCart.csrf;
    etag = freshCart.etag;
    patchRes = patchCart(BASE_URL, csrf, cartId, etag, quantity);
  }

  if (patchRes.status < 200 || patchRes.status >= 300) {
    throw new Error('cart patch failed status ' + patchRes.status + ' body ' + patchRes.body);
  }

  const patchEtag = getHeader(patchRes, 'ETag');
  if (patchEtag) etag = patchEtag;

  if (patchRes.body && patchRes.body.length > 0) {
    try {
      const patchData = JSON.parse(patchRes.body);
      if (patchData && patchData.csrf) csrf = patchData.csrf;
    } catch (e) {
      // patch response may be empty; not an error
    }
  }

  const idempotencyKey = 'order-' + cartId + '-' + vu + '-' + iter;
  let orderRes = postOrder(BASE_URL, csrf, cartId, etag, idempotencyKey);

  if (orderRes.status === 412) {
    const freshCart = getCart(BASE_URL, cartId);
    if (freshCart.csrf) csrf = freshCart.csrf;
    etag = freshCart.etag;
    orderRes = postOrder(BASE_URL, csrf, cartId, etag, idempotencyKey);
  }

  if (orderRes.status !== 201) {
    throw new Error('order failed status ' + orderRes.status + ' body ' + orderRes.body);
  }

  const orderData = parseJson(orderRes, 'order');
  if (!orderData.accepted) {
    throw new Error('order accepted:false: ' + orderRes.body);
  }
}

