            product = d["product"]
        elif "products" in d and isinstance(d["products"], list) and d["products"]:
            product = d["products"][0]
    else:
        if "id" in data and "variants" in data:
            product = data
        elif "product" in data and isinstance(data["product"], dict):
            product = data["product"]
        elif "products" in data and isinstance(data["products"], list) and data["products"]:
            product = data["products"][0]

    return product, next_url


def safe_json(resp):
    try:
        return resp.json()
    except Exception:
        return None


