            return
        data = safe_json(resp)
        if isinstance(data, dict) and "etag" in data:
            self.cart_etag = data["etag"]

    def do_login(self):
        with self.client.get(
            "/v2/login-form",
            catch_response=True,
            name="login_form",
            allow_redirects=False,
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"login_form expected 200, got {resp.status_code}")
                return False

            csrf = extract_csrf(resp.text)
            if not csrf:
                resp.failure("login_form missing csrf")
                return False
            self.csrf = csrf

        payload = {"username": self.username, "password": self.password, "csrf": self.csrf}
        with self.client.post(
            "/v2/login",
            json=payload,
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            name="login",
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 200:
                data = safe_json(resp)
                if not isinstance(data, dict):
                    resp.failure("login 200 non-JSON")
                    return False
                self.csrf = data.get("csrf", self.csrf)
                return True

            if resp.status_code == 302:
                location = resp.headers.get("Location")
                if not location:
                    resp.failure("login 302 missing Location")
                    return False
                resp.success()

                with self.client.get(
                    location,
                    catch_response=True,
                    name="login_redirect",
                    allow_redirects=False,
                ) as redirected:
                    if redirected.status_code != 200:
                        redirected.failure(
                            f"login redirect expected 200, got {redirected.status_code}"
                        )
                        return False
                    data = safe_json(redirected)
                    if not isinstance(data, dict):
                        redirected.failure("login redirect non-JSON")
                        return False
                    self.csrf = data.get("csrf", self.csrf)
                    return True

            resp.failure(f"login expected 200/302, got {resp.status_code}")
            return False

    def renew_session(self):
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            name="session_renew",
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 200:
                data = safe_json(resp)
                if isinstance(data, dict):
                    self.csrf = data.get("csrf", self.csrf)
                return True

            if resp.status_code == 401:
                body = safe_json(resp)
                if isinstance(body, dict) and body.get("error") == "session":
                    resp.success()
                    return False
                resp.failure(f"renew 401 {body}")
                return False

            resp.failure(f"renew expected 200, got {resp.status_code}")
            return False

    def recover_cart(self):
        if not self.cart_id:
            return True

        with self.client.post(
            f"/v2/carts/{self.cart_id}/recover",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            catch_response=True,
            name="cart_recover",
            allow_redirects=False,
        ) as resp:
            if resp.status_code in (200, 201):
                data = safe_json(resp)
                if isinstance(data, dict):
                    self.csrf = data.get("csrf", self.csrf)
                self.update_etag_from_response(resp)
                return True

            if resp.status_code == 401:
                body = safe_json(resp)
                if isinstance(body, dict) and body.get("error") == "denied":
                    resp.failure("cart recovery denied")
                else:
                    resp.failure(f"cart recovery 401 {body}")
                return False

            resp.failure(
                f"cart recovery expected 200/201, got {resp.status_code}"
            )
            return False

    def expire_renew_recover(self):
        if not self.renew_session():
            return False
        return self.recover_cart()

    def revoked_relogin_recover(self):
        if not self.do_login():
            return False
        return self.recover_cart()

    def refresh_cart_etag(self):
        if not self.cart_id:
            return False

        with self.client.get(
            f"/v2/carts/{self.cart_id}",
            catch_response=True,
            name="get_cart",
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 200:
                self.update_etag_from_response(resp)
                data = safe_json(resp)
                if isinstance(data, dict):
                    self.csrf = data.get("csrf", self.csrf)
                return True

            resp.failure(f"get cart expected 200, got {resp.status_code}")
            return False

    def auth_post(
        self,
        path,
        json_data,
        op_name,
        expected_statuses=(200, 201),
        use_if_match=False,
        headers_extra=None,
        handle_412=False,
    ):
        recovered = False
        retried_412 = False

        while True:
            headers = {"X-CSRF-Token": self.csrf}
            if headers_extra:
                headers.update(headers_extra)
            if use_if_match and self.cart_etag:
                headers["If-Match"] = self.cart_etag

            with self.client.post(
                path,
                json=json_data,
                headers=headers,
                catch_response=True,
                name=op_name,
                allow_redirects=False,
            ) as resp:
                if resp.status_code in expected_statuses:
                    self.update_csrf_from_response(resp)
                    return resp

                if resp.status_code == 412 and handle_412 and not retried_412:
                    resp.success()
                    retried_412 = True
                    if not self.refresh_cart_etag():
                        resp.failure(f"{op_name}: cannot refresh ETag after 412")
                        return None
                    continue

                if resp.status_code == 401:
                    body = safe_json(resp)
                    if not isinstance(body, dict):
                        resp.failure(f"{op_name}: 401 non-JSON")
                        return None

                    error = body.get("error")
                    if error == "expired":
                        resp.success()
                        if recovered:
                            resp.failure(f"{op_name}: still expired after recovery")
                            return None
                        recovered = True
                        if not self.expire_renew_recover():
                            resp.failure(f"{op_name}: expiry recovery failed")
                            return None
                        continue

                    if error == "session":
                        resp.success()
                        if recovered:
                            resp.failure(f"{op_name}: still session after recovery")
                            return None
                        recovered = True
                        if not self.revoked_relogin_recover():
                            resp.failure(f"{op_name}: session recovery failed")
                            return None
                        continue

                    if error == "denied":
                        resp.failure(f"{op_name}: denied is not expiry")
                        return None

                    resp.failure(f"{op_name}: 401 unknown {body}")
                    return None

                resp.failure(
                    f"{op_name}: expected {expected_statuses}, got {resp.status_code}"
                )
                return None

