        with self.client.get(
            "/v2/catalog",
            catch_response=True,
            name="catalog",
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 200:
                data = safe_json(resp)
                if isinstance(data, dict):
                    product, _ = find_product_and_next(data)
                    if product:
                        for variant in product.get("variants", []):
                            if variant.get("in_stock"):
                                return product.get("id"), variant.get("id")
            else:
                resp.failure(f"catalog expected 200, got {resp.status_code}")

        next_url = "/v2/catalog/page"
        for _ in range(3):
            if not next_url:
                break

            with self.client.get(
                next_url,
                catch_response=True,
                name="catalog_page",
                allow_redirects=False,
            ) as resp:
                if resp.status_code != 200:
                    resp.failure(f"catalog page expected 200, got {resp.status_code}")
                    return None, None

                data = safe_json(resp)
                if not isinstance(data, dict):
                    resp.failure("catalog page non-JSON")
                    return None, None

                product, next_relative = find_product_and_next(data)
                if product:
                    for variant in product.get("variants", []):
                        if variant.get("in_stock"):
                            return product.get("id"), variant.get("id")

                next_url = next_relative

        return None, None

    def create_cart(self, product_id, variant_id):
        payload = {"product_id": product_id, "variant_id": variant_id}
        resp = self.auth_post(
            "/v2/carts",
            payload,
            "create_cart",
            expected_statuses=(201,),
            use_if_match=False,
        )
        if resp is None:
            return None

        data = safe_json(resp)
        if not isinstance(data, dict):
            resp.failure("create_cart non-JSON")
            return None

        cart_id = data.get("id")
        if not cart_id:
            resp.failure("create_cart missing id")
            return None

        self.cart_id = cart_id
        self.csrf = data.get("csrf", self.csrf)
        self.update_etag_from_response(resp)
        self.idempotency_key = f"idem-{cart_id}-{uuid.uuid4()}"
        return cart_id

    def checkout(self):
        if not self.cart_id or not self.idempotency_key:
            return None

        payload = {"cart_id": self.cart_id}
        headers_extra = {"Idempotency-Key": self.idempotency_key}

        resp = self.auth_post(
            "/v2/orders",
            payload,
            "create_order",
            expected_statuses=(201,),
            use_if_match=True,
            headers_extra=headers_extra,
            handle_412=True,
        )
        if resp is None:
            return None

        data = safe_json(resp)
        if not isinstance(data, dict):
            resp.failure("create_order non-JSON")
            return None

        if data.get("accepted") is not True:
            resp.failure("create_order accepted false")
            return None

        self.csrf = data.get("csrf", self.csrf)
        return data.get("id")

    def execute_journey(self):
        self.csrf = None
        self.cart_id = None
        self.cart_etag = None
        self.idempotency_key = None

        if not self.do_login():
            return

        product_id, variant_id = self.get_product_variant()
        if product_id is None or variant_id is None:
            return

        if not self.create_cart(product_id, variant_id):
            return

        if self.cart_etag is None:
            self.refresh_cart_etag()

        if not self.checkout():
            return

    @task
    def journey(self):
        self.iter_count += 1
        self.execute_journey()

        if self.iter_count >= self.max_iterations:
            raise StopUser()


class VariantA(BaseJourneyUser):
    profile = {"expire_after": 2}


class VariantB(BaseJourneyUser):
    profile = {
        "expire_after": 2,
        "html_layout": 1,
        "reverse_catalog": True,
    }


class JourneyShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.started = False
        self.active = False

    def tick(self):
        if not self.started:
            self.started = True
            return {VariantA.__name__: 1, VariantB.__name__: 1}

        if self.runner.user_count > 0:
            self.active = True
            return {VariantA.__name__: 1, VariantB.__name__: 1}

        if self.active:
            return None

        return {VariantA.__name__: 1, VariantB.__name__: 1}
