def get_attr(tag, attr):
    escaped = re.escape(attr)
    m = re.search(r"\b" + escaped + r'\s*=\s*(["\'])(.*?)\1', tag, re.I | re.S)
    if m:
        return m.group(2)
    m = re.search(r"\b" + escaped + r'\s*=\s*([^\s>]+)', tag, re.I)
    if m:
