def get_input_value(html, input_name):
    for tag in re.finditer(r"<input\b[^>]*>", html, re.I | re.S):
        tag_text = tag.group(0)
        if get_attr(tag_text, "name") == input_name:
            value = get_attr(tag_text, "value")
            return value if value is not None else ""
    return None


