class ReservationShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self._started = False
        self._spawn_complete = False
        self._start_time = None

    def tick(self):
        if not self._started:
            self._started = True
            self._start_time = time.time()
            return (2, 2)

        user_count = self.runner.user_count if self.runner is not None else 0

        if not self._spawn_complete:
            # Keep trying to reach the two required users, but do not respawn forever.
            if user_count >= 2 or time.time() - self._start_time > 5:
                self._spawn_complete = True
                return (user_count, 0)
            return (2, 2)

        if user_count == 0:
            return None
        return (user_count, 0)
