      http("POST /v2/carts")
          .post("/v2/carts")
          .body(StringBody(session -> String.format("{\"product_id\":\"%s\",\"variant_id\":\"%s\",\"grant_id\":\"%s\"}",
              session.get("product").toString(), session.get("variant").toString(), session.getString("grant"))))
          .check(header("ETag").optional().saveAs("etag"))
          .check(jsonPath("$.csrf").optional().saveAs("csrf"))
          .check(jsonPath("$.id").optional().saveAs("cart"))
          .check(regex("\"id\"\\s*:\\s*\"cart-").find().exists())
  );

  private ChainBuilder createOrder = exec(
      http("POST /v2/orders")
          .post("/v2/orders")
          .body(StringBody(session -> String.format("{\"cart_id\":\"%s\"}", session.getString("cart"))))
          .check(header("ETag").optional().saveAs("etag"))
          .check(jsonPath("$.csrf").optional().saveAs("csrf"))
          .check(regex("\"accepted\"\\s*:\\s*true").find().exists())
  );

  private ChainBuilder initUsername = exec(session -> {
    long uid = session.userId();
    long n = Math.floorMod(uid, 16L) + 1L;
    return session.set("username", "bench-" + n);
  });

  private ScenarioBuilder scn = scenario("CookieCSRFShop")
      .exec(initUsername)
      .repeat(2, "iteration").on(
          exec(flushCookieJar()),
          exec(resetVars),
          exec(getLoginForm),
          exec(postLogin),
          doIf(session -> "true".equals(session.getString("redirect"))).then(
              exec(followLoginRedirect)
          ),
          exec(getCatalog),
          exec(createCart),
          exec(createOrder)
      );

  {
    setUp(
        scn.injectOpen(atOnceUsers(2))
    ).protocols(httpProtocol);
  }
}
