import os
import json
import re
import itertools

from locust import HttpUser, LoadTestShape, task, between
from locust.exception import StopUser

ITERATIONS = 2

FIXTURE_DIR = "/fixtures"

def _read_accounts():
    for name in ("m04-accounts.json", "accounts.json"):
        path = os.path.join(FIXTURE_DIR, name)
        if os.path.exists(path):
            with open(path, "r", encoding="utf-8") as f:
                return json.load(f)
    raise FileNotFoundError("accounts fixture not found in /fixtures")

ACCOUNTS = _read_accounts()
ACCOUNT_CYCLE = itertools.cycle(ACCOUNTS)

def _extract_csrf_from_html(text):
    for tag_match in re.finditer(r"<input\b[^>]*>", text, re.IGNORECASE):
        tag = tag_match.group(0)
        if re.search(r"\bname\s*=\s*[\"']csrf[\"']", tag, re.IGNORECASE):
            val_match = re.search(r"\bvalue\s*=\s*[\"']([^\"']*)[\"']", tag, re.IGNORECASE)
            if val_match:
                return val_match.group(1)
    return None


class BaseShopUser(HttpUser):
    wait_time = between(0, 0)
    started_users = 0
    completed_users = 0

    def on_start(self):
        BaseShopUser.started_users += 1
        self.account = next(ACCOUNT_CYCLE)
        self.iterations_done = 0
        self.username = self.account["username"]
        self.quantity = int(self.account["quantity"])
        self.csrf = None
        self.grant_id = None
        self.cart_id = None
        self.etag = None

    @task
    def journey(self):
        if self.iterations_done >= ITERATIONS:
            BaseShopUser.completed_users += 1
            raise StopUser()
        self.iterations_done += 1
        self._run_journey()

    def _run_journey(self):
        self.client.cookies.clear()
        self.csrf = None
        self.grant_id = None
        self.cart_id = None
        self.etag = None

        if not self._login():
            return
        product_id, variant_id = self._get_catalog_selection()
        if product_id is None:
            return
        if not self._create_cart(product_id, variant_id):
            return
        if not self._patch_cart():
            return
        self._post_order()

    def _headers(self):
        headers = {}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf
        return headers

    def _json_or_none(self, resp):
        try:
            return resp.json()
        except Exception:
            return None

    def _extract_error(self, resp):
        data = self._json_or_none(resp)
        if isinstance(data, dict):
            return data.get("error")
        return None

    def _update_etag(self, resp):
        etag = resp.headers.get("ETag") or resp.headers.get("Etag")
        if etag:
            self.etag = etag

    def _login(self):
        form_csrf = self._get_login_form()
        if form_csrf is None:
            return False
        return self._post_login(form_csrf)

    def _get_login_form(self):
        with self.client.get(
            "/v2/login-form",
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"GET /v2/login-form unexpected status {resp.status_code}")
                return None
            csrf = _extract_csrf_from_html(resp.text)
            if csrf is None:
                resp.failure("GET /v2/login-form did not contain a csrf input")
                return None
            return csrf

    def _post_login(self, form_csrf):
        headers = self._headers()
        headers["Content-Type"] = "application/json"
        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": "bench", "csrf": form_csrf},
            headers=headers,
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code == 401:
                err = self._extract_error(resp)
                resp.failure(f"login denied (401 {err})")
                return False
            if resp.status_code not in (200, 302):
                resp.failure(f"POST /v2/login unexpected status {resp.status_code}")
                return False

            data = self._json_or_none(resp)
            if isinstance(data, dict):
                if data.get("csrf"):
                    self.csrf = data["csrf"]

            location = resp.headers.get("Location")
            if resp.status_code == 302:
                if location is None:
                    resp.failure("POST /v2/login returned 302 without Location")
                    return False
                return self._get_login_location(location)
            return True

    def _get_login_location(self, location):
        with self.client.get(
            location,
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"GET login Location {location} unexpected status {resp.status_code}")
                return False

            data = self._json_or_none(resp)
            if isinstance(data, dict):
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                if data.get("grant_id") is not None:
                    self.grant_id = data["grant_id"]
                return True

            if self._try_challenge_form(resp.text):
                return True

            resp.failure("login Location did not return grant_id or csrf")
            return False

    def _try_challenge_form(self, html):
        action_match = re.search(
            r"<form\b[^>]*\baction\s*=\s*[\"']([^\"']+)[\"']",
            html,
            re.IGNORECASE,
        )
        if not action_match:
            return False

        action = action_match.group(1)
        if not re.search(r"\bname\s*=\s*[\"']challenge[\"']", html, re.IGNORECASE):
            return False

        challenge_value = ""
        val_match = re.search(
            r"<input\b(?=[^>]*\bname\s*=\s*[\"']challenge[\"'])(?=[^>]*\bvalue\s*=\s*[\"']([^\"']*)[\"'])[^>]*>",
            html,
            re.IGNORECASE,
        )
        if val_match:
            challenge_value = val_match.group(1)

        headers = self._headers()
        headers["Content-Type"] = "application/json"
        with self.client.post(
            action,
            json={"challenge": challenge_value},
            headers=headers,
            allow_redirects=False,
            catch_response=True,
        ) as challenge_resp:
            if challenge_resp.status_code != 302:
                challenge_resp.failure(f"challenge POST status {challenge_resp.status_code}")
                return False

            next_location = challenge_resp.headers.get("Location")
            if next_location is None:
                challenge_resp.failure("challenge POST lacked Location header")
                return False

            with self.client.get(
                next_location,
                allow_redirects=False,
                catch_response=True,
            ) as grant_resp:
                if grant_resp.status_code != 200:
                    grant_resp.failure(f"challenge grant Location status {grant_resp.status_code}")
                    return False

                data = self._json_or_none(grant_resp)
                if not isinstance(data, dict) or data.get("grant_id") is None:
                    grant_resp.failure("challenge grant Location returned no grant_id")
                    return False

                self.grant_id = data.get("grant_id")
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                return True

    def _get_catalog_selection(self):
        with self.client.get(
            "/v2/catalog",
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"GET /v2/catalog unexpected status {resp.status_code}")
                return None, None

            data = self._json_or_none(resp)
            if not isinstance(data, dict) or not isinstance(data.get("data"), dict):
                resp.failure("GET /v2/catalog returned invalid JSON shape")
                return None, None

