            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code == 401:
                err = self._error_from_response(resp)
                resp.failure(f"POST /v2/login denied 401 {err}")
                return False

            if resp.status_code not in (200, 302):
                resp.failure(f"POST /v2/login unexpected status {resp.status_code}")
                return False

            data = self._json_or_none(resp)
            if isinstance(data, dict) and data.get("csrf"):
                self.csrf = data["csrf"]

            if resp.status_code == 302:
                location = resp.headers.get("Location")
                if location is None:
                    resp.failure("POST /v2/login returned 302 without Location")
                    return False
                return self._get_login_location(location)

            return True

    def _get_login_location(self, location):
        with self.client.get(
            location,
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"GET login Location unexpected status {resp.status_code}")
                return False

            data = self._json_or_none(resp)
            if isinstance(data, dict):
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                if data.get("grant_id") is not None:
                    self.grant_id = data["grant_id"]
                return True

            if self._try_challenge_form(resp.text):
                return True

            resp.failure("login Location returned neither grant_id nor csrf")
            return False

    def _try_challenge_form(self, html):
        if not re.search(r"""\bname\s*=\s*["']challenge["']""", html, re.IGNORECASE):
            return False

        action_match = FORM_ACTION_RE.search(html)
        if not action_match:
            return False

        challenge_value = ""
        challenge_match = CHALLENGE_INPUT_RE.search(html)
        if challenge_match:
            challenge_value = challenge_match.group(1)

        with self.client.post(
            action_match.group(1),
            json={"challenge": challenge_value},
            headers=self._mutation_headers(),
            allow_redirects=False,
            catch_response=True,
        ) as challenge_resp:
            if challenge_resp.status_code != 302:
                challenge_resp.failure(f"challenge POST unexpected status {challenge_resp.status_code}")
                return False

            next_location = challenge_resp.headers.get("Location")
            if next_location is None:
                challenge_resp.failure("challenge POST returned 302 without Location")
                return False

            with self.client.get(
                next_location,
                allow_redirects=False,
                catch_response=True,
            ) as grant_resp:
                if grant_resp.status_code != 200:
                    grant_resp.failure(f"challenge grant Location unexpected status {grant_resp.status_code}")
                    return False

                data = self._json_or_none(grant_resp)
                if not isinstance(data, dict) or data.get("grant_id") is None:
                    grant_resp.failure("challenge grant Location returned no grant_id")
                    return False

                self.grant_id = data["grant_id"]
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                return True

    # ---------- catalog and cart ----------

    def _get_catalog_selection(self):
        with self.client.get(
            "/v2/catalog",
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"GET /v2/catalog unexpected status {resp.status_code}")
                return None, None

            data = self._json_or_none(resp)
            if not isinstance(data, dict) or not isinstance(data.get("data"), dict):
                resp.failure("GET /v2/catalog returned invalid body")
                return None, None

            if data.get("csrf"):
                self.csrf = data["csrf"]

            products = data["data"].get("products") or []
            if isinstance(products, list):
                for product in products:
                    if not isinstance(product, dict):
                        continue
                    variants = product.get("variants") or []
                    if isinstance(variants, list) and variants and variants[0].get("in_stock") is True:
                        return product.get("id"), variants[0].get("id")

                for product in products:
                    if not isinstance(product, dict):
                        continue
                    for variant in product.get("variants") or []:
                        if isinstance(variant, dict) and variant.get("in_stock") is True:
                            return product.get("id"), variant.get("id")

            resp.failure("GET /v2/catalog contained no in-stock product")
            return None, None

    def _create_cart(self, product_id, variant_id):
        body = {
            "product_id": str(product_id),
            "variant_id": str(variant_id),
        }
        if self.grant_id is not None:
            body["grant_id"] = str(self.grant_id)

        with self.client.post(
            "/v2/carts",
            json=body,
            headers=self._mutation_headers(),
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code != 201:
                resp.failure(f"POST /v2/carts unexpected status {resp.status_code}")
                return False

            data = self._json_or_none(resp)
            if not isinstance(data, dict) or data.get("id") is None:
                resp.failure("POST /v2/carts returned no cart id")
                return False

            self.cart_id = str(data["id"])
            if data.get("csrf"):
                self.csrf = data["csrf"]
            self._update_etag(resp)
            return True

    def _patch_cart(self):
        if not self.cart_id:
            return False

        url = f"/v2/carts/{self.cart_id}"
        payload = {"quantity": self.quantity}

        for attempt in (1, 2):
            with self.client.patch(
                url,
                json=payload,
                headers=self._mutation_headers(),
                allow_redirects=False,
                catch_response=True,
            ) as resp:
                if resp.status_code == 200:
                    self._update_from_response(resp)
                    return True

                if resp.status_code == 412 and attempt == 1:
                    resp.success()
                    if not self._read_cart_for_etag():
                        return False
                    continue

                if resp.status_code == 401:
                    err = self._error_from_response(resp)
                    if err in ("expired", "session") and attempt == 1:
                        resp.success()
                        if not self._recover_session(err):
                            return False
                        continue
                    if err in ("expired", "session"):
                        resp.failure(f"PATCH {url} returned 401 {err} after retry")
                        return False
                    resp.failure(f"PATCH {url} denied 401 {err}")
                    return False

                resp.failure(f"PATCH {url} unexpected status {resp.status_code}")
                return False

        return False

    def _read_cart_for_etag(self):
        if not self.cart_id:
            return False

        url = f"/v2/carts/{self.cart_id}"
        with self.client.get(
            url,
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"GET {url} unexpected status {resp.status_code}")
                return False

            etag = resp.headers.get("ETag") or resp.headers.get("Etag")
            if not etag:
                resp.failure(f"GET {url} returned 200 without ETag")
                return False

            self._update_etag(resp)
            data = self._json_or_none(resp)
            if isinstance(data, dict) and data.get("csrf"):
                self.csrf = data["csrf"]
            return True

    # ---------- order ----------

    def _post_order(self):
        if not self.cart_id:
            return False

        payload = {"cart_id": self.cart_id}
        url = "/v2/orders"

        for attempt in (1, 2):
            with self.client.post(
                url,
                json=payload,
                headers=self._mutation_headers(idempotency_key=self.cart_id),
                allow_redirects=False,
                catch_response=True,
            ) as resp:
                if resp.status_code == 201:
                    data = self._json_or_none(resp)
                    if isinstance(data, dict) and data.get("accepted") is True:
                        self._update_from_response(resp)
                        return True
                    resp.failure(f"POST /v2/orders 201 but accepted not true: {data}")
                    return False

                if resp.status_code == 200:
                    data = self._json_or_none(resp)
                    resp.failure(f"POST /v2/orders returned HTTP 200 business failure: {data}")
                    return False

                if resp.status_code == 401:
                    err = self._error_from_response(resp)
                    if err in ("expired", "session") and attempt == 1:
                        resp.success()
                        if not self._recover_session(err):
                            return False
                        continue
                    if err in ("expired", "session"):
                        resp.failure(f"POST /v2/orders returned 401 {err} after retry")
                        return False
                    resp.failure(f"POST /v2/orders denied 401 {err}")
                    return False

                resp.failure(f"POST /v2/orders unexpected status {resp.status_code}")
                return False

        return False

    # ---------- recovery helpers ----------

    def _recover_session(self, err):
        if err == "expired":
            if not self._renew_session():
                return False
        else:  # session
            if not self._renew_session():
                if not self._fresh_login():
                    return False

        if self.cart_id and not self._recover_cart():
            return False
        return True

    def _renew_session(self):
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers=self._mutation_headers(),
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code in (200, 201):
                self._update_from_response(resp)
                return True

            if resp.status_code == 401 and self._error_from_response(resp) == "session":
                resp.success()
                return False

            resp.failure(f"POST /v2/session/renew unexpected status {resp.status_code}")
            return False

    def _fresh_login(self):
        self.client.cookies.clear()
        self.csrf = None
        self.grant_id = None

        form_csrf = self._get_login_form()
        if form_csrf is None:
            return False
        return self._post_login(form_csrf)

    def _recover_cart(self):
        if not self.cart_id:
            return True

        url = f"/v2/carts/{self.cart_id}/recover"
        with self.client.post(
            url,
            json={},
            headers=self._mutation_headers(),
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code in (200, 201):
                self._update_from_response(resp)
                return True

            resp.failure(f"POST {url} unexpected status {resp.status_code}")
            return False

    # ---------- helpers ----------

    def _mutation_headers(self, idempotency_key=None):
        headers = {"Content-Type": "application/json"}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf
        if self.etag:
            headers["If-Match"] = self.etag
        if idempotency_key:
            headers["Idempotency-Key"] = idempotency_key
        return headers

    def _json_or_none(self, resp):
        try:
            return resp.json()
        except Exception:
            return None

    def _error_from_response(self, resp):
        data = self._json_or_none(resp)
        if isinstance(data, dict):
            return data.get("error")
        return None

    def _update_etag(self, resp):
        etag = resp.headers.get("ETag") or resp.headers.get("Etag")
        if etag:
            self.etag = etag

    def _update_from_response(self, resp):
        data = self._json_or_none(resp)
        if isinstance(data, dict) and data.get("csrf"):
            self.csrf = data["csrf"]
        self._update_etag(resp)


class ShopLoadShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self._started = False

    def tick(self):
        if not self._started:
            self._started = True
            return (TOTAL_USERS, TOTAL_USERS)

        if ShopUser.completed_users >= TOTAL_USERS:
            return None

        return (TOTAL_USERS, 0)
