import java.time.Duration;
import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

public class ModelSimulation extends Simulation {

    HttpProtocolBuilder httpProtocol = http
        .baseUrl(System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000"))
        .disableFollowRedirect()
        .acceptHeader("application/json")
        .header("Content-Type", "application/json")
        .header("X-CSRF-Token", "#{csrf}")
        .header("If-Match", "#{etag}")
        .header("Idempotency-Key", "#{cart}")
        .disableCaching();

    ChainBuilder resetSession = exec(session -> session
        .set("csrf", "MISSING")
        .set("cart", "MISSING")
        .set("etag", "MISSING")
        .set("hasCart", false)
        .set("grant", "MISSING")
        .set("product", "MISSING")
        .set("variant", "MISSING")
        .set("quantity", "2")
        .set("username", "bench-" + session.userId())
        .remove("location")
    );

    ChainBuilder loginForm = exec(
        http("GET /v2/login-form")
            .get("/v2/login-form")
            .check(
                status().is(200),
                regex("<input(?=[^>]*\\bname=[\"']csrf[\"'])(?=[^>]*\\bvalue=[\"']([^\"']+)[\"'])[^>]*>")
                    .find(1)
                    .saveAs("form"),
                jsonPath("$.csrf").optional().saveAs("csrf"),
                header("ETag").optional().saveAs("etag"),
                regex("\"error\"\\s*:\\s*\"(?:expired|session)\"").optional().saveAs("recover")
            )
    );

    ChainBuilder login = exec(
        http("POST /v2/login")
            .post("/v2/login")
            .body(StringBody("{\"username\":\"#{username}\",\"password\":\"bench\",\"csrf\":\"#{form}\"}"))
            .check(
                status().is(200).or(status().is(302)),
                jsonPath("$.csrf").optional().saveAs("csrf"),
                header("Location").optional().saveAs("location"),
                header("ETag").optional().saveAs("etag"),
                regex("\"error\"\\s*:\\s*\"(?:expired|session)\"").optional().saveAs("recover")
            )
    );

    ChainBuilder followRedirect = exec(
        http("GET login redirect")
            .get(session -> session.getString("location"))
            .check(
                status().is(200),
                jsonPath("$.csrf").optional().saveAs("csrf"),
                jsonPath("$.grant_id").optional().saveAs("grant"),
                header("ETag").optional().saveAs("etag"),
                regex("\"error\"\\s*:\\s*\"(?:expired|session)\"").optional().saveAs("recover")
            )
    );

    ChainBuilder catalog = exec(
        http("GET /v2/catalog")
            .get("/v2/catalog")
            .check(
                status().is(200),
                jsonPath("$.csrf").optional().saveAs("csrf"),
                header("ETag").optional().saveAs("etag"),
                jsonPath("$.data.products[?(@.variants[0].in_stock == true)].id")
                    .find(1).saveAs("product"),
                jsonPath("$.data.products[?(@.variants[0].in_stock == true)].variants[0].id")
                    .find(1).saveAs("variant"),
                regex("\"error\"\\s*:\\s*\"(?:expired|session)\"").optional().saveAs("recover")
            )
    );

    ChainBuilder createCart = exec(
        http("POST /v2/carts")
            .post("/v2/carts")
            .body(StringBody("{\"product_id\":\"#{product}\",\"variant_id\":\"#{variant}\",\"grant_id\":\"#{grant}\"}"))
            .check(
                status().is(201),
                jsonPath("$.csrf").optional().saveAs("csrf"),
                jsonPath("$.id").saveAs("cart"),
                header("ETag").optional().saveAs("etag"),
                regex("\"id\"\\s*:\\s*\"cart-").exists(),
                regex("\"error\"\\s*:\\s*\"(?:expired|session)\"").optional().saveAs("recover")
            )
    );

    ChainBuilder checkout = exec(
        http("POST /v2/orders")
            .post("/v2/orders")
            .body(StringBody("{\"cart_id\":\"#{cart}\"}"))
            .check(
                status().is(201),
                jsonPath("$.csrf").optional().saveAs("csrf"),
                header("ETag").optional().saveAs("etag"),
                regex("\"accepted\"\\s*:\\s*true").exists(),
                regex("\"error\"\\s*:\\s*\"(?:expired|session)\"").optional().saveAs("recover")
            )
    );

    ChainBuilder journey = exec(resetSession)
        .exec(loginForm)
        .exec(login)
        .exec(doIf(session -> {
            String loc = session.getString("location");
            return loc != null && !loc.isEmpty();
        }).then(followRedirect))
        .exec(catalog)
        .exec(createCart)
        .exec(checkout);

    ScenarioBuilder scn = scenario("ModelScenario")
        .exec(session -> session.set("startTime", System.currentTimeMillis()))
        .asLongAs(session -> System.currentTimeMillis() - session.getLong("startTime") < 38000L)
            .on(
                exec(pace(Duration.ofSeconds(2)))
                .exec(journey)
            );

    {
        setUp(
            scn.injectOpen(rampUsers(4).during(Duration.ofSeconds(2)))
        ).protocols(httpProtocol).maxDuration(Duration.ofSeconds(45));
    }
}
