                    .find(1).saveAs("product"),
                jsonPath("$.data.products[?(@.variants[0].in_stock == true)].variants[0].id")
                    .find(1).saveAs("variant"),
                header("ETag").optional().saveAs("etag")
            )
    );

    ChainBuilder createCart = exec(
        http("POST /v2/carts")
            .post("/v2/carts")
            .body(StringBody("{\"product_id\":\"#{product}\",\"variant_id\":\"#{variant}\",\"grant_id\":\"#{grant}\"}"))
            .check(
                status().is(201),
                jsonPath("$.csrf").optional().saveAs("csrf"),
                jsonPath("$.id").saveAs("cart"),
                header("ETag").optional().saveAs("etag"),
                regex("\"id\"\\s*:\\s*\"cart-").exists()
            )
    );

    ChainBuilder checkout = exec(
        http("POST /v2/orders")
            .post("/v2/orders")
            .body(StringBody("{\"cart_id\":\"#{cart}\"}"))
            .check(
                status().is(201),
                jsonPath("$.csrf").optional().saveAs("csrf"),
                header("ETag").optional().saveAs("etag"),
                regex("\"accepted\"\\s*:\\s*true").exists()
            )
    );

    ChainBuilder journey = exec(resetSession)
        .exec(loginForm)
        .exec(login)
        .exec(doIf(session -> {
            String loc = session.getString("location");
            return loc != null && !loc.isEmpty();
        }).then(followRedirect))
        .exec(catalog)
        .exec(createCart)
        .exec(checkout);

    ScenarioBuilder scn = scenario("ModelScenario")
        .exec(session -> session.set("startTime", System.currentTimeMillis()))
        .asLongAs(session -> System.currentTimeMillis() - session.getLong("startTime") < 38000L)
            .on(
                exec(pace(Duration.ofMillis(1980)))
                    .exec(journey)
            );

    {
        setUp(
            scn.injectOpen(atOnceUsers(4))
        ).protocols(httpProtocol).maxDuration(Duration.ofSeconds(45));
    }
}

