            extra_headers["If-Match"] = self.etag

        def validate(resp):
            if resp.status_code not in (200, 201):
                resp.failure(f"order status {resp.status_code}: {resp.text[:200]}")
                return False

            try:
                data = resp.json()
            except Exception as exc:
                resp.failure(f"order json invalid: {exc}")
                return False

            if data.get("accepted") is not True:
                resp.failure("order accepted false")
                return False

            self.csrf = data.get("csrf", self.csrf)
            self.committed = True
            resp.success()
            return True

        return self._post_authenticated(
            "/v2/orders",
            payload,
            validate,
            extra_headers=extra_headers,
        )

    def _journey_impl(self):
        # Every journey starts a fresh login and a fresh cart.
        self.grant_id = "MISSING"
        self.product = None
        self.variant = None
        self.cart_id = "MISSING"
        self.etag = "MISSING"
        self.has_cart = False
        self.committed = False

        if not self._login():
            return False
        if not self._catalog():
            return False
        if not self._create_cart():
            return False
        if not self._checkout():
            return False
        return True

    @task
    def journey(self):
        self.last_task_start = time.monotonic()

        self._journey_impl()

        self.iteration += 1
        if self.max_iterations and self.iteration >= self.max_iterations:
            raise StopUser()
