                .body(StringBody(session -> "{\"username\":\"" + username(session) + "\",\"password\":\""
                    + password(session) + "\",\"csrf\":\"" + session.getString("formCsrf") + "\"}"))
                .check(status().in(200, 302), jsonPath("$.csrf").optional().saveAs("csrf"),
                    jsonPath("$.grant_id").optional().saveAs("grant"),
                    header("Location").optional().saveAs("location")))
            .exec(doIf(session -> session.contains("location")).then(
                exec(http("login redirect").get("#{location}").header("X-CSRF-Token", "#{csrf}")
                    .check(jsonPath("$.grant_id").optional().saveAs("grant"),
                        jsonPath("$.csrf").optional().saveAs("csrf")))));
    }

    private static ChainBuilder challenge() {
        return exec(http("challenge form").get("/v2/challenge-form").header("X-CSRF-Token", "#{csrf}")
                .check(bodyString().saveAs("challengeHtml")))
            .exec(session -> {
                String html = session.getString("challengeHtml");
                Matcher action = Pattern.compile("(?i)<form[^>]*\\baction=[\\\"']([^\\\"']+)[\\\"']")
                    .matcher(html);
                Matcher token = Pattern.compile("(?i)<input(?=[^>]*\\bname=[\\\"']challenge[\\\"'])"
                    + "(?=[^>]*\\bvalue=[\\\"']([^\\\"']+)[\\\"'])[^>]*>").matcher(html);
                return action.find() && token.find()
                    ? session.set("challengeAction", action.group(1)).set("challengeToken", token.group(1))
                    : session;
            })
            .exec(http("challenge submit").post("#{challengeAction}")
                .disableFollowRedirect()
                .header("Content-Type", "application/json").header("X-CSRF-Token", "#{csrf}")
                .body(StringBody(session -> "{\"challenge\":\"" + session.getString("challengeToken") + "\"}"))
                .check(status().in(200, 302), header("Location").optional().saveAs("location"),
                    jsonPath("$.grant_id").optional().saveAs("grant"),
                    jsonPath("$.csrf").optional().saveAs("csrf")))
            .exec(doIf(session -> session.contains("location")).then(
                exec(http("challenge redirect").get("#{location}").header("X-CSRF-Token", "#{csrf}")
                    .check(jsonPath("$.grant_id").optional().saveAs("grant"),
                        jsonPath("$.csrf").optional().saveAs("csrf")))));
    }

    private static Duration retryDelay(Session session) {
        try {
            return Duration.ofMillis(Math.max(10,
                (long) (Double.parseDouble(session.getString("retryAfter")) * 1000 + 10)));
        } catch (RuntimeException error) {
            return Duration.ofMillis(20);
        }
    }

    private static ChainBuilder workRequest(String path) {
        ChainBuilder chain = exec(
            http("work").post(path)
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{}"))
                .check(
                    status().saveAs("workStatus"),
                    status().not(500),
                    header("Retry-After").optional().saveAs("retryAfter"),
                    jsonPath("$.csrf").optional().saveAs("csrf"),
                    jsonPath("$.error").optional().saveAs("apiError"),
                    checkIf(session -> session.getInt("workStatus") == 401)
                        .then(jsonPath("$.error").in("expired", "session"))
                )
        );

        if (MODE.equals("errors")) {
            chain = chain.exec(
                doIf(session -> session.getInt("workStatus") == 401).then(
                    exec(http("renew").post("/v2/session/renew")
                        .header("Content-Type", "application/json")
                        .header("X-CSRF-Token", "#{csrf}")
                        .body(StringBody("{}"))
                        .check(status().is(200), jsonPath("$.csrf").optional().saveAs("csrf")))
                        .exec(
                            http("work retry").post(path)
                                .header("Content-Type", "application/json")
                                .header("X-CSRF-Token", "#{csrf}")
                                .body(StringBody("{}"))
                                .check(
                                    status().saveAs("workStatus"),
                                    status().not(500),
                                    header("Retry-After").optional().saveAs("retryAfter"),
                                    jsonPath("$.csrf").optional().saveAs("csrf"),
                                    jsonPath("$.error").optional().saveAs("apiError"),
                                    checkIf(session -> session.getInt("workStatus") == 401)
                                        .then(jsonPath("$.error").in("expired", "session"))
                                )
                        )
                )
            );
        }

        if (CFG.path("completion").asBoolean(false)) {
            for (int retry = 0; retry < 4; retry++) {
                chain = chain.exec(
                    doIf(session -> session.getInt("workStatus") == 429).then(
                        pause(session -> retryDelay(session)).exec(
                            http("work retry").post(path)
                                .header("Content-Type", "application/json")
                                .header("X-CSRF-Token", "#{csrf}")
                                .body(StringBody("{}"))
                                .check(
                                    status().saveAs("workStatus"),
                                    status().not(500),
                                    header("Retry-After").optional().saveAs("retryAfter"),
                                    jsonPath("$.csrf").optional().saveAs("csrf"),
                                    jsonPath("$.error").optional().saveAs("apiError"),
                                    checkIf(session -> session.getInt("workStatus") == 401)
                                        .then(jsonPath("$.error").in("expired", "session"))
                                )
                        )
                    )
                );
            }
        }

        return chain;
    }

    private static ChainBuilder work(String path) {
        return login().exec(workRequest(path));
    }

    private static Session selectProduct(Session session) {
        try {
            JsonNode products = JSON.readTree(session.getString("catalogBody"))
                .path("data").path("products");
            for (JsonNode product : products) {
                for (JsonNode variant : product.path("variants")) {
                    if (variant.path("in_stock").asBoolean()) {
                        return session.set("product", product.path("id").asText())
                            .set("variant", variant.path("id").asText());
                    }
                }
            }
        } catch (IOException error) {
            return session;
        }
        return session;
    }

    private static boolean isRetryable401(Session session, String statusKey, String errorKey) {
        try {
            Integer status = session.getInt(statusKey);
            String error = session.getString(errorKey);
            return Integer.valueOf(401).equals(status)
                && ("expired".equals(error) || "session".equals(error));
        } catch (RuntimeException error) {
            return false;
        }
    }

    private static Session saveRecoverySession(Session session) {
        return session.set("recoveryCart", session.getString("cart"))
            .set("recoveryEtag", session.getString("etag"))
            .set("recoveryProduct", session.getString("product"))
            .set("recoveryVariant", session.getString("variant"))
            .set("recoveryGrant", session.getString("grant"));
    }

    private static Session restoreRecoverySession(Session session) {
        return session.set("cart", session.getString("recoveryCart"))
            .set("etag", session.getString("recoveryEtag"))
            .set("product", session.getString("recoveryProduct"))
            .set("variant", session.getString("recoveryVariant"))
            .set("grant", session.getString("recoveryGrant"));
    }

    private static ChainBuilder recoverSession(boolean cartExists) {
        ChainBuilder chain = exec(
            http("session renew").post("/v2/session/renew")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody("{}"))
                .check(
                    status().saveAs("renewStatus"),
                    jsonPath("$.error").optional().saveAs("renewError"),
                    jsonPath("$.csrf").optional().saveAs("csrf")
                )
        );

        chain = chain.exec(
            doIf(session -> session.getInt("renewStatus") != 200).then(
                exec(session -> saveRecoverySession(session))
                    .exec(login())
                    .exec(session -> restoreRecoverySession(session))
            )
        );

        if (cartExists) {
            chain = chain.exec(
                doIf(session -> session.getString("cart") != null).then(
                    exec(
                        http("cart recover").post("/v2/carts/#{cart}/recover")
                            .header("Content-Type", "application/json")
                            .header("X-CSRF-Token", "#{csrf}")
                            .body(StringBody("{}"))
                            .check(
                                status().is(200),
                                header("ETag").optional().saveAs("etag"),
                                jsonPath("$.csrf").optional().saveAs("csrf")
                            )
                    )
                )
            );
        }

        return chain;
    }

    private static ChainBuilder denialCatalog() {
        ChainBuilder chain = exec(
            http("catalog").get("/v2/catalog")
                .header("X-CSRF-Token", "#{csrf}")
                .check(
                    status().saveAs("catalogStatus"),
                    bodyString().saveAs("catalogBody"),
                    jsonPath("$.error").optional().saveAs("apiError"),
                    jsonPath("$.csrf").optional().saveAs("csrf"),
                    checkIf(session -> session.getInt("catalogStatus") == 401)
                        .then(jsonPath("$.error").in("expired", "session"))
                )
        );

        chain = chain.exec(
            doIf(session -> isRetryable401(session, "catalogStatus", "apiError")).then(
                exec(recoverSession(false))
                    .exec(
                        http("catalog retry").get("/v2/catalog")
                            .header("X-CSRF-Token", "#{csrf}")
                            .check(
                                status().is(200),
                                bodyString().saveAs("catalogBody"),
                                jsonPath("$.csrf").optional().saveAs("csrf")
                            )
                    )
            )
        );

        chain = chain.exec(session -> selectProduct(session));
        chain = chain.exec(
            doIf(session -> session.getString("product") == null || session.getString("variant") == null)
                .then(exec(session -> session.markAsFailed()))
        );

        return chain;
    }

    private static ChainBuilder denialCart() {
        ChainBuilder chain = exec(
            http("cart").post("/v2/carts")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody(session -> "{\"product_id\":\"" + session.getString("product")
                    + "\",\"variant_id\":\"" + session.getString("variant")
                    + "\",\"grant_id\":\"" + session.getString("grant") + "\"}"))
                .check(
                    status().saveAs("cartStatus"),
                    jsonPath("$.id").optional().saveAs("cart"),
                    header("ETag").optional().saveAs("etag"),
                    jsonPath("$.csrf").optional().saveAs("csrf"),
                    jsonPath("$.error").optional().saveAs("apiError"),
                    checkIf(session -> session.getInt("cartStatus") == 401)
                        .then(jsonPath("$.error").in("expired", "session"))
                )
        );

        chain = chain.exec(
            doIf(session -> isRetryable401(session, "cartStatus", "apiError")).then(
                exec(recoverSession(false))
                    .exec(
                        http("cart retry").post("/v2/carts")
                            .header("Content-Type", "application/json")
                            .header("X-CSRF-Token", "#{csrf}")
                            .body(StringBody(session -> "{\"product_id\":\"" + session.getString("product")
                                + "\",\"variant_id\":\"" + session.getString("variant")
                                + "\",\"grant_id\":\"" + session.getString("grant") + "\"}"))
                            .check(
                                status().saveAs("cartStatus"),
                                jsonPath("$.id").saveAs("cart"),
                                header("ETag").optional().saveAs("etag"),
                                jsonPath("$.csrf").optional().saveAs("csrf")
                            )
                    )
            )
        );

        chain = chain.exec(
            doIf(session -> session.getInt("cartStatus") != 200 && session.getInt("cartStatus") != 201)
                .then(exec(session -> session.markAsFailed()))
        );
        chain = chain.exec(
            doIf(session -> session.getString("cart") == null)
                .then(exec(session -> session.markAsFailed()))
        );

        return chain;
    }

    private static ChainBuilder denialCheckout() {
        ChainBuilder chain = exec(
            http("checkout").post("/v2/orders")
                .header("Content-Type", "application/json")
                .header("X-CSRF-Token", "#{csrf}")
                .header("Idempotency-Key", "#{cart}")
                .header("If-Match", "#{etag}")
                .body(StringBody(session -> "{\"cart_id\":\"" + session.getString("cart") + "\"}"))
                .check(
                    status().saveAs("orderStatus"),
                    jsonPath("$.accepted").optional().saveAs("accepted"),
                    jsonPath("$.csrf").optional().saveAs("csrf"),
                    jsonPath("$.error").optional().saveAs("apiError"),
                    checkIf(session -> session.getInt("orderStatus") == 401)
                        .then(jsonPath("$.error").in("expired", "session"))
                )
        );

        chain = chain.exec(
            doIf(session -> isRetryable401(session, "orderStatus", "apiError")).then(
                exec(recoverSession(true))
                    .exec(
                        http("checkout retry").post("/v2/orders")
                            .header("Content-Type", "application/json")
                            .header("X-CSRF-Token", "#{csrf}")
                            .header("Idempotency-Key", "#{cart}")
                            .header("If-Match", "#{etag}")
                            .body(StringBody(session -> "{\"cart_id\":\"" + session.getString("cart") + "\"}"))
                            .check(
                                status().saveAs("orderStatus"),
                                jsonPath("$.accepted").optional().saveAs("accepted"),
                                jsonPath("$.csrf").optional().saveAs("csrf")
                            )
                    )
            )
        );

        chain = chain.exec(
            doIf(session -> session.getInt("orderStatus") != 201)
                .then(exec(session -> session.markAsFailed()))
        );
        chain = chain.exec(
            doIf(session -> session.getInt("orderStatus") == 201
                    && !"true".equals(session.getString("accepted")))
                .then(exec(session -> session.markAsFailed()))
        );

        return chain;
