  const renew = raw('/v2/session/renew', 'POST', {});
  if (renew.status !== 200) {
    grant = '';
    csrf = '';
    login();
  }
}

function request(path, method = 'GET', data = null, extra = {}) {
  let r = raw(path, method, data, extra);

  if (r.status === 401) {
    const parsedBody = body(r);
    if (parsedBody.error === 'expired' || parsedBody.error === 'session') {
      recoverSession();
      if (cart) {
        raw('/v2/carts/' + cart + '/recover', 'POST', {});
      }
      r = raw(path, method, data, extra);
    }
  }

  return r;
}

function work(override) {
  if (!csrf) login();
  const path = override || '/v2/work';
  let r = request(path, 'POST', {});

  for (let n = 0; n < 4 && r.status === 429; n++) {
    const retryAfter = Number(getHeader(r, 'Retry-After') || 1);
    sleep(retryAfter + 0.01);
    r = request(path, 'POST', {});
  }

  check(r, { work: (r) => (r.status === 200 && body(r).ok === true) || r.status === 429 });
}

function flow() {
  csrf = '';
  cart = '';
  grant = '';
  login();

  if (cfg.mode === 'challenge') {
    let r = request('/v2/challenge-form');
    const action = findFormAction(r.body, '/v2/challenges/');
    const challenge = findInputValueByName(r.body, 'challenge');

    if (!action || !challenge) {
      check(false, { 'challenge form': (x) => false });
      return;
    }

    r = request(action, 'POST', { challenge: challenge });
    if (r.status === 302) {
      const location = getHeader(r, 'Location');
      if (location) {
        r = raw(location);
        const parsedBody = body(r);
        if (parsedBody.grant_id) grant = parsedBody.grant_id;
      }
    }
  }

  let page = cfg.mode === 'pagination' ? '/v2/catalog/page' : '/v2/catalog';
  let product = null;

  for (let n = 0; n < 3 && page; n++) {
    const r = request(page);
    const parsedBody = body(r);
    const products = (parsedBody.data && parsedBody.data.products) || [];
    product = products.find((p) => p.variants && p.variants.some((v) => v.in_stock));
    if (product) break;
    page = parsedBody.next || null;
  }

  if (!product) {
    check(false, { 'eligible product': (x) => false });
    return;
  }

  const variant = product.variants.find((v) => v.in_stock);
  const cartPayload = { product_id: product.id, variant_id: variant.id };
  if (grant) cartPayload.grant_id = grant;

  let r = request('/v2/carts', 'POST', cartPayload);
  cart = String(body(r).id || '');
  let etag = getHeader(r, 'ETag');

  check(r, { cart: (r) => r.status === 201 && cart !== '' });
  if (!cart) return;

  if (cfg.mode === 'etag' || cfg.mode === 'data') {
    const quantity = cfg.mode === 'data' ? rows[(__VU - 1) % rows.length].quantity : cfg.quantity;
    const headers = { 'If-Match': etag };
    r = request('/v2/carts/' + cart, 'PATCH', { quantity: quantity }, headers);

    if (r.status === 412) {
      const read = request('/v2/carts/' + cart);
      etag = getHeader(read, 'ETag') || etag;
      r = request('/v2/carts/' + cart, 'PATCH', { quantity: quantity }, { 'If-Match': etag });
    }

    etag = getHeader(r, 'ETag') || etag;
    check(r, { update: (r) => r.status === 200 });
  }

  let reservation_id;
  if (cfg.mode === 'reservation') {
    r = request('/v2/reservations', 'POST', { cart_id: cart });
    const statusUrl = body(r).status_url;

    for (let n = 0; n < 5; n++) {
      sleep(0.05);
      r = request(statusUrl);
      const parsedBody = body(r);

      if (parsedBody.status === 'ready') {
        reservation_id = parsedBody.reservation_id;
        break;
      }

      if (parsedBody.status === 'failed') {
        check(false, { 'reservation ready': (x) => false });
        return;
      }
    }

    if (!reservation_id) {
      check(false, { 'reservation ready': (x) => false });
      return;
    }
  }

  const orderHeaders = { 'Idempotency-Key': cart };
  if (etag) orderHeaders['If-Match'] = etag;

  const orderPayload = { cart_id: cart };
  if (reservation_id) orderPayload.reservation_id = reservation_id;

  r = request('/v2/orders', 'POST', orderPayload, orderHeaders);
  check(r, { accepted: (r) => r.status === 201 && body(r).accepted === true });
}

export default function () {
  if (cfg.workload) {
    if (cfg.operation === 'journey') flow();
