                (normalized_path.startswith('/v2/jobs/') and response.status_code < 400
                 and body.get('status') == 'failed')
                or (normalized_path == '/v2/orders' and method == 'POST'
                    and response.status_code < 400
                    and body.get('accepted') is not True)
            )
