                raise StopUser()
            if pool.get('operation') == 'journey':
                self.flow()
            else:
                self.work(pool['path'])
            return
        if MODE == 'errors':
            self.login()
            for _ in range(4):
                self.work()
        else:
            self.flow()
        self.iteration += 1
        if self.iteration >= CFG.get('iterations', 2):
            raise StopUser()

