import os
import re
import time
from itertools import count
from urllib.parse import urljoin

import gevent
from locust import HttpUser, LoadTestShape, task, constant
from locust.exception import StopUser


T0 = None
SLOT_INDEX = 0
USER_SEQ = count(1)


def get_attr(tag, attr_name):
    m = re.search(r"\b" + re.escape(attr_name) + r"\s*=\s*([\"'])(.*?)\1", tag, re.I | re.S)
    if m:
        return m.group(2)
    m = re.search(r"\b" + re.escape(attr_name) + r"\s*=\s*([^\s\"'>]+)", tag, re.I | re.S)
    if m:
        return m.group(1)
    return None


def extract_csrf(html):
    if not html:
        return None
    for tag in re.findall(r"<input\b[^>]*>", html, re.I | re.S):
        name = get_attr(tag, "name")
        if name and name.lower() == "csrf":
            return get_attr(tag, "value")
    return None


def parse_body(resp):
    try:
        data = resp.json()
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def slot_time(idx):
    if idx < 75:
        return idx / 5.0
    if idx < 225:
        return (idx + 150) / 15.0
    return (idx - 100) / 5.0


def schedule_slot():
    global T0, SLOT_INDEX
    now = time.time()
    if T0 is None:
        T0 = now
        idx = 0
        SLOT_INDEX = 1
        return idx, now

    idx = SLOT_INDEX
    t = slot_time(idx)
    if t >= 35.0:
        return None, None

    SLOT_INDEX += 1
    return idx, T0 + t


def get_retry_after(resp):
    val = resp.headers.get("Retry-After")
    try:
        return float(val)
    except Exception:
        return 1.0


class WorkUser(HttpUser):
    wait_time = constant(0)

    def on_start(self):
        self.username = f"bench-{next(USER_SEQ)}"
        self.csrf = None
        if not self.login():
            raise StopUser()

    def login(self):
        resp = self.client.get(
            "/v2/login-form",
            allow_redirects=False,
            name="/v2/login-form",
            catch_response=True,
        )
        if resp.status_code != 200:
            resp.failure(f"login form status {resp.status_code}")
            return False

        csrf = extract_csrf(resp.text)
        if not csrf:
            resp.failure("login form missing csrf")
            return False

