    def run_work(self):
        global WORK_DONE

        while not WORK_DONE:
            due = next_due()
            if due is None:
                gevent.sleep(0.5)
                WORK_DONE = True
                break

            delay = due - time.time()
            if delay > 0:
                gevent.sleep(delay)

            if T0 is not None and time.time() > T0 + 40:
                break

            self.do_work()

        raise StopUser()


