import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import java.time.Duration;

public class ModelSimulation extends Simulation {

    private String baseUrl = System.getenv("BASE_URL") != null ? System.getenv("BASE_URL") : "http://127.0.0.1:8000";

    private HttpProtocolBuilder httpProtocol = http
        .baseUrl(baseUrl)
        .disableAutoRedirect()
        .acceptHeader("application/json")
        .contentTypeHeader("application/json")
        .userAgentHeader("gatling")
        .shareConnections;

    private ChainBuilder initUser = exec(session -> {
        long uid = session.userId();
        String username = "bench-" + (Math.floorMod(uid - 1, 16) + 1);
        return session.set("username", username);
    });

    private ChainBuilder getLoginForm = exec(
        http("GET /v2/login-form")
            .get("/v2/login-form")
            .check(status().is(200))
            .check(css("input[name=csrf]", "value").saveAs("csrf"))
    );

    private ChainBuilder postLogin = exec(
        http("POST /v2/login")
            .post("/v2/login")
            .body(StringBody("{\"username\":\"${username}\",\"password\":\"bench\",\"csrf\":\"${csrf}\"}"))
            .check(status().in(200, 302))
            .check(jsonPath("$.csrf").optional().saveAs("csrf"))
            .check(header("Location").optional().saveAs("loginLocation"))
    );

    private ChainBuilder followLoginRedirect = exec(
        doIf(session -> session.contains("loginLocation"))
            .on(
                exec(
                    http("GET login redirect")
                        .get(session -> session.getString("loginLocation"))
                        .check(status().is(200))
                        .check(jsonPath("$.csrf").optional().saveAs("csrf"))
                )
            )
    );

    private ChainBuilder workAttempt = exec(session -> session.set("workAttempts", session.getInt("workAttempts") + 1))
        .exec(
            http("POST /v2/work")
                .post("/v2/work")
                .header("X-CSRF-Token", "${csrf}")
                .body(StringBody("{}"))
                .check(status().saveAs("workStatus"))
                .check(bodyString().saveAs("workBody"))
                .check(jsonPath("$.csrf").optional().saveAs("csrf"))
        )
        .exec(session -> {
            int status = session.getInt("workStatus");
            if (status == 200) {
                String body = session.getString("workBody");
                if (body != null && (body.contains("\"ok\":true") || body.contains("\"ok\": true"))) {
                    return session.set("workSuccess", true);
                }
                return session.markAsFailed();
            } else if (status == 429) {
                return session.set("workSuccess", false);
            } else {
                return session.markAsFailed();
            }
        });

    private ChainBuilder work = exec(session -> session.set("workAttempts", 0).set("workSuccess", false))
        .exec(workAttempt)
        .asLongAs(session -> !session.getBoolean("workSuccess") && session.getInt("workAttempts") < 5)
            .on(
                pause(Duration.ofSeconds(1)).exec(workAttempt)
            )
        .exec(session -> {
            if (!session.getBoolean("workSuccess")) {
                return session.markAsFailed();
            }
            return session;
        });

    private ScenarioBuilder workScenario = scenario("WorkScenario")
        .exec(initUser)
        .exec(getLoginForm)
        .exec(postLogin)
        .exec(followLoginRedirect)
        .exec(work);

    {
        setUp(
            workScenario.injectOpen(
                constantUsersPerSec(5).during(Duration.ofSeconds(15)),
                constantUsersPerSec(15).during(Duration.ofSeconds(10)),
                constantUsersPerSec(5).during(Duration.ofSeconds(10))
            ).protocols(httpProtocol)
        ).maxDuration(Duration.ofSeconds(45));
    }
}
