import os
import re
import time

from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser

EXPECTED_RESPONSE_TIME = 0.2


class G:
    start_time = None
    t0 = None
    target_rate = 5
    user_count = 0
    stop = False
    user_counter = 0


def _safe_json(resp):
    try:
        return resp.json() or {}
    except Exception:
        return {}


def _extract_csrf(html):
    if not html:
        return None
    patterns = [
        r'<input[^>]*name=["\']csrf["\'][^>]*value=["\']([^"\']+)["\'][^>]*>',
        r'<input[^>]*value=["\']([^"\']+)["\'][^>]*name=["\']csrf["\'][^>]*>',
        r'<input[^>]*name=csrf[^>]*value=["\']([^"\']+)["\'][^>]*>',
        r'<input[^>]*value=["\']([^"\']+)["\'][^>]*name=csrf[^>]*>',
    ]
    for pattern in patterns:
        match = re.search(pattern, html, re.I | re.S)
        if match:
            return match.group(1)
    return None


def _error_type(resp):
    data = _safe_json(resp)
    if isinstance(data, dict):
        return data.get("error")
    return None


def _retry_after_seconds(resp, default=1.0):
    value = resp.headers.get("Retry-After")
    if value is None:
        return default
    try:
        return max(0.05, float(value))
    except Exception:
        return default


def desired_users(target_rate):
    if target_rate <= 0:
        return 0
    return max(2, min(32, int(target_rate * EXPECTED_RESPONSE_TIME) + 2))


class WorkShape(LoadTestShape):
    def tick(self):
        now = time.monotonic()

        if G.start_time is None:
            G.start_time = now

        if G.t0 is None:
            target = 5
            users = desired_users(target)
            G.target_rate = target
            G.user_count = users
            G.stop = False
            return (users, 10)

        elapsed = now - G.t0

        if elapsed < 35:
            if elapsed < 5:
                target = 5
            elif elapsed < 15:
                target = 5
            elif elapsed < 25:
                target = 15
            else:
                target = 5

            G.target_rate = target
            G.user_count = desired_users(target)
            G.stop = False
            return (G.user_count, 10)

        if elapsed < 40:
            if not G.stop:
                G.stop = True
            G.target_rate = 0
            G.user_count = 0
            return (0, 10)

        return None


class WorkUser(HttpUser):
    host = os.environ.get("BASE_URL", "http://127.0.0.1:8000")

    def on_start(self):
        self.csrf = None
        self.username = self._next_username()
        if not self.login():
            raise StopUser()

    def wait_time(self):
        if G.stop:
            return 1.0
        if G.target_rate <= 0 or G.user_count <= 0:
            return 0.2

        interval_per_user = G.user_count / G.target_rate
        wait = interval_per_user - EXPECTED_RESPONSE_TIME
        return max(0.0, wait)

    @task
    def work_operation(self):
        if G.stop:
            raise StopUser()
        self.do_work()

    def _next_username(self):
        idx = G.user_counter % 17
        G.user_counter += 1
        if idx == 16:
            return "bench"
        return f"bench-{idx + 1}"

    def _update_csrf_from_response(self, resp):
        self._update_csrf(_safe_json(resp))

    def _update_csrf(self, data):
        if isinstance(data, dict) and data.get("csrf"):
            self.csrf = data["csrf"]

    def _get_login_redirect(self, location):
        with self.client.get(
            location,
            name="/v2/login-redirect",
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code < 400:
                self._update_csrf_from_response(resp)
                resp.success()
                return True
            resp.failure(f"login redirect status {resp.status_code}")
            return False

    def login(self):
        with self.client.get(
            "/v2/login-form",
            name="/v2/login-form",
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code != 200:
                resp.failure(f"login-form status {resp.status_code}")
                return False

            csrf = _extract_csrf(resp.text)
            if not csrf:
                resp.failure("login-form missing csrf")
                return False

            resp.success()
            self.csrf = csrf

        status = None
        location = None

        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": "bench", "csrf": self.csrf},
            headers={"X-CSRF-Token": self.csrf},
            name="/v2/login",
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            status = resp.status_code
            if status in (200, 201):
                self._update_csrf_from_response(resp)
                resp.success()
            elif status == 302:
                location = resp.headers.get("Location")
                if not location:
                    resp.failure("login 302 missing Location")
                    return False
                resp.success()
            else:
                resp.failure(f"login status {status}")
                return False

        if status in (200, 201):
            return True

        if status == 302:
            return self._get_login_redirect(location)

        return False

    def renew_session(self):
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            name="/v2/session/renew",
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            if resp.status_code < 400:
                self._update_csrf_from_response(resp)
                resp.success()
                return True

            if resp.status_code == 401:
                resp.success()
                return False

            resp.failure(f"session renew status {resp.status_code}")
            return False

    def do_work(self):
        if G.t0 is None:
            G.t0 = time.monotonic()

        scheduled_retries = 0
        recovery_retry_used = False

        while True:
            if G.stop:
                return False

            should_retry = False
            retry_after = None
            error = None

            with self.client.post(
                "/v2/work",
                json={},
                headers={"X-CSRF-Token": self.csrf},
                name="/v2/work",
                allow_redirects=False,
                catch_response=True,
            ) as resp:
                status = resp.status_code

                if status < 400:
                    data = _safe_json(resp)
                    if data.get("ok") is True:
                        self._update_csrf(data)
                        resp.success()
                        return True
                    resp.failure("work response not ok")
                    return False

                if status == 429:
                    resp.success()
                    scheduled_retries += 1
                    if scheduled_retries > 4:
                        return False
                    retry_after = _retry_after_seconds(resp)
                    should_retry = True

                elif status == 401:
                    error = _error_type(resp)
                    if error in ("expired", "session"):
                        resp.success()
                    else:
                        resp.failure(f"work 401 {error}")
                        return False

                    if recovery_retry_used:
                        return False
                    recovery_retry_used = True
                    should_retry = True

                else:
                    resp.failure(f"unexpected work status {status}")
                    return False

            if should_retry and retry_after is not None:
                time.sleep(retry_after)
                if G.stop:
                    return False
                continue

            if should_retry and error is not None:
                if error == "expired":
                    recovered = self.renew_session()
                    if not recovered:
                        recovered = self.login()
                else:
                    recovered = self.login()

                if not recovered:
                    return False

                if G.stop:
                    return False
                continue

            if should_retry:
                continue

            return False
